import { apiGroups,apiOperations,apiSchemas } from './api-documentation.mjs';

const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const section=(title,...paragraphs)=>({title,paragraphs});
export const productChapters=[
  ['platform','Platform administration','Separate staff sign-in, workspace provisioning and account access controls.',[
    section('Sign in separately','Open app.drykraft.com/sa with an explicitly created platform account. Workspace owners and administrators do not receive platform access. New platform accounts must add DryKraft platform to their own authenticator and enter a six-digit code before entering the console. Keep the ten recovery codes private; each works once. Use existing authenticator or recovery proof for later sign-in. Platform sessions end after 15 minutes without a successful platform request and expire after four hours.','Platform owner manages staff accounts and global settings. Owner/administrator manages workspace and customer account access; support can inspect management directories, while billing can inspect saved subscriptions. Read-only accounts cannot change state. Role/status changes end affected staff sessions. At least one active platform owner is retained.'),
    section('Inspect and control customer access','Use Workspaces or Users, search by name/email/address, then open the detail page. Directories show safe identity, membership and saved subscription information. Business records, passwords and provider credentials are excluded. A workspace suspension pauses shared access and background billing checks while retaining stored data. A customer account disable ends that person’s sessions across workspaces, retaining memberships and account credentials. Restoration requires a fresh customer sign-in and still follows membership/subscription permissions.','Each status change needs a saved version, meaningful reason and confirmation. If another administrator changed the item, reload and review its saved status. Immutable audit records the change. Read platform audit separately from the customer workspace audit trail.'),
    section('Provision and invite an owner','Choose Workspaces - Create workspace. Enter the company name, unoccupied address, owner email, default/enabled currencies, named timezone and provisioning reason. Creation atomically initializes standard objects, a sales pipeline, dashboard and seven-day owner invitation. The 15-day trial starts at workspace creation. It creates no customer user or membership until acceptance.','Copy the private invitation link from the result and share it with the named recipient; this operation does not send an email. Existing recipients sign in with their own password and authenticator when enabled. New recipients create their account during acceptance. Expired/revoked links or an issuer whose authority changed cannot grant ownership. Replaying an accepted invitation cannot recreate membership that was removed. Identical provisioning retries reuse the saved workspace; keep the request ID and inputs unchanged. The setup page keeps its request ID in the address, so the original staff account can reload to recover a saved result after a timeout.'),
    section('Commercial administration API','Platform owners, administrators and billing staff can create and publish versioned plans through the platform API, then assign a specific immutable version to a workspace. Publishing a new version does not change existing assignments. Price metadata is configured per immutable plan version; this catalog does not create a Dodo product or collect payment. The monthly/annual checkout API and customer selector are deployed. Successful payment and paid renewal acceptance remain pending. Enterprise versions have negotiated prices rather than an invented amount.','The current live-resource ceilings cover workspace memberships, unmerged People contacts, custom records outside the seven built-in objects, pipelines, all workflows, active workflows, enabled calendars and integrations. Integration counts include saved workflow credentials and enabled outreach/calendar connections and customer webhooks. Null means no ceiling at that level; zero prevents growth. Downstream overrides may only reduce the plan. Concurrent creation checks the same workspace lock; a lower ceiling retains existing records and prevents further growth. Pausing or disabling a resource can free its active allowance.','The API can extend a trial to a later date within the next 90 days, or record an enterprise agreement with a reference, start/end dates and seat allowance. A current agreement can grant workspace access; expiry or insufficient seats removes that agreement grant. It does not fabricate a paid provider subscription. Plan, agreement and trial changes require a current version and reason and publish immutable audit and lifecycle events. Commercial console forms are deployed after bounded browser acceptance and a fresh finish review. Plans opens immutable versions, Workspaces opens saved plan/limits, and administrative changes require a reason and review. Consumed usage, credit settlement, successful payment and paid renewal acceptance, coupons, add-ons and the remaining reseller operations remain unfinished.'),
    section('Scoped reseller API access','Open Resellers - an organization - API keys in Superadmin. Owners/admins can create or revoke a key; read-only platform accounts can inspect its metadata. The directory paginates 25 keys and exact detail pages show current status, prefix, permissions and expiry. Pending or unavailable contracts prevent new issuance while leaving inspection and revocation available.','Platform owners/admins can issue an expiring API key for one approved reseller and selected customer directory, retail catalog or aggregate resource usage reads. Copy its secret on creation; it is stored only as a digest and never returned again. A saved setup request can be retried with the same request ID, but its replay returns metadata without the secret. The masked one-time copy includes an eye control and copy action. Save it securely and confirm before continuing. Leaving does not revoke the key. A setup URL contains only the request ID: reopening it recovers current safe metadata for the original issuing account, including after expiry or revocation, without recovering a token. If a response is interrupted, check the exact saved request before repeating identical input. Open the saved key, revoke a lost key and explicitly create a replacement. Revocation needs the current revision, review and audit reason; check the saved status before repeating an unknown revocation. Expiry is within 90 days; scope and expiry cannot be edited.','Use the dedicated Bearer key at /api/v1/reseller on app.drykraft.com. Browser cookies and customer service-account keys are not accepted. Every read rechecks key, current reseller status and contract. Transferred customers disappear from the prior reseller’s directory. Requests are limited to 120 per minute per key and completed reads append immutable metadata-only audit. These keys grant no customer CRM, financial record, message, provider credential or platform access. Customer provisioning and the remaining reseller write operations have separate unfinished release scope. Reseller staff identities and their portal use separate password/MFA sessions, not these Bearer keys.'),
    section('Reseller commercial API foundation','The reseller commercial APIs and platform console manage commercial organizations and inherited allowances. The Resellers menu opens contract, wholesale grant, retail plans and customer detail pages; a workspace opens its commercial parent. Platform owners/admins can create a pending organization with contract dates, an explicit customer access policy and a versioned wholesale grant. Approval is separate. Wholesale grants reduce a selected platform plan and define per-workspace ceilings, shared live-resource ceilings, maximum customer count and trial allowance. Publishing a lower grant retains existing customer records and blocks growth above the new ceiling.','Approved resellers with current contracts can receive versioned retail packages through the platform API. Catalog currency, monthly/annual/setup minor-unit prices and trial days are immutable per version. Console amounts use the selected currency’s major units, including KWD’s three-decimal precision; changing currency explicitly clears draft prices for fresh review. A customer’s version link opens its assigned historical package. Retail allowances cannot exceed current wholesale limits; customer assignments stay pinned when a new retail version is published. Effective customer allowances intersect the existing platform plan/overrides, current wholesale grant and assigned retail version. Concurrent resource growth and customer transfers check shared capacity atomically.','A reasoned customer assignment or transfer preserves CRM records, memberships and provider billing. It grants no CRM access. Suspension can retain customer access or explicitly suspend it, including an expired contract; no customer data is deleted. These APIs expose safe commercial metadata and aggregate counts only. Billing mode and retail prices are metadata: provider collection, consumed usage/credits, customer provisioning, snapshots, support approval and branding/domains remain unfinished.'),
    section('Reseller staff portal and organization team','Platform owners/admins can open Resellers - an organization - Team to create a separate staff account or attach an existing reseller staff account. The first enabled member must be an owner. New accounts need a privately shared initial password of at least 12 characters; this operation sends no invitation email. Each person enrolls their own authenticator at app.drykraft.com/reseller and saves their ten one-time recovery codes. Customer and platform credentials cannot sign in as reseller staff.','After sign-in, choose one of your active contracted organizations. Pending or unavailable organizations remain labeled in your own directory. Owner/admin roles manage team access and retail publications; administrators cannot create, promote or manage owners. Billing can inspect retail catalog and aggregate resource use. Support can inspect linked workspace metadata and aggregate resources. None of these roles grants access to customer CRM, finance records, users or provider credentials. A changed role or membership ends the affected person’s reseller sessions across organizations. Keep at least one enabled owner.','Retail plans opens your catalog and immutable version detail. Owners/admins choose a fixed plan key, supported currency, monthly/annual/setup prices, trial and eight resource ceilings plus included modules. Enter prices in major units, including three decimal places for KWD. Changing currency does not convert them. Review the actual definition and audit reason before publishing. Current wholesale allowance is rechecked at commit; publishing does not collect payment or automatically change customer assignments. A customer’s plan link opens its pinned historical version.','The setup URL carries a request ID, not a password or form contents. Reopening it with the original authorized account recovers an already saved membership or retail publication. After an interrupted response, check the same saved request; do not create a second request blindly. Unsaved navigation asks whether to keep editing or discard. Reload saved access before retrying an uncertain membership change. Account security remains available during a contract pause: rotate your own password with current password plus unused proof, replace recovery codes, or end other sessions. Password rotation ends prior sessions and clears organization selection. Staff sessions have a four-hour maximum and 15-minute request idle timeout.'),
    section('Reseller customer management in local development','The local implementation adds customer workspace creation for current reseller owners/admins, using an exact retail version, owner email, currencies and timezone. Creation stores configuration and a pending seven-day invitation without creating a user or membership. The original actor can recover a saved request; unchanged retries create one workspace. Disabled Sales or zero pipeline allowance skips the default pipeline. The local portal has linked customer detail pages and a Create customer workspace form. These additions are browser-verified in isolated sample workspaces and are not deployed yet.','Current organization staff can read safe customer metadata. Owners/admins may rename or pause/resume their customer; billing staff may assign a bounded retail version. Changes need the current control or assignment version and a reason. Resuming does not bypass platform suspension or billing. Plan changes preserve existing provider billing and trial dates. Private invitation links are restricted to their actual current issuer; renewal rotates the link, revocation invalidates it and accepted links cannot recreate removed ownership. These local APIs do not dispatch mail, charge customers or grant staff access to customer records. On the local customer detail page, each control opens a reasoned review with its access, billing or invitation consequences. Unfinished changes protect navigation; finish or cancel a change before refreshing saved details. Conflicting or interrupted responses require loading saved customer state before another review. A private link is masked with show/hide, copy and hide actions and remains only in memory. An existing invited recipient can sign in with their own customer account and join; staff credentials do not accept customer ownership. Invitation mail, scoped key write APIs, background setup, platform invitation visibility and production deployment remain required.'),
    section('Renew, revoke or email an owner invitation','Open the workspace detail to inspect the invited owner and current status. Owner/admin staff may renew an unaccepted invitation for seven days or revoke its private link, with a reason and the current version. Renewal replaces the old token without sending email. Accepted ownership is managed separately. To reveal or email a valid link, you must be its current issuing administrator; renew under your account if another administrator issued it. Suspended workspaces cannot share invitations.','Email invitation first shows the actual recipient, sender, subject and body for explicit review. Sending requires enabled, verified platform SMTP. DryKraft refuses changed invitation, template, connection or composed content after review. Identical retries reuse the same queued job. One recent send per invitation version per ten minutes and three per workspace each hour prevent rapid duplicates. Revocation cancels queued messages; a message already in flight may arrive with an unusable link.'),
    section('Platform email templates, connection and history','Open Email - Invitation template to edit the plain-text subject and body as owner/admin staff. Keep {{invite_url}} and use only the listed placeholders. Preview uses fictional details and sends nothing. Each save creates an immutable version; queued messages retain their saved content. Unsaved changes need explicit discard before navigation. Support, billing and viewer staff can inspect the template but cannot edit it.','Email - SMTP connection is visible to owner/admin staff, and only owners can save it. Use a public SMTP host and TLS port 465 or 587. The saved password is never returned; leave the field blank to retain it. Enabling verifies access without sending. A connection change cancels queued jobs tied to its older version. Delivery history shows queued, sending, accepted, failed, unknown or cancelled outcomes. Accepted means SMTP acceptance, not confirmed inbox delivery. Unknown outcomes are never automatically resent; inspect the mail provider before sending again.'),
    section('Settings, subscriptions and scope','Platform settings can open/close new account registration and configure the public support email and maintenance notice. Only platform owners save these versioned settings. Subscriptions shows saved provider status, purchased seats, trial/renewal dates and sync time; viewing or suspending an account does not charge or refund money.','This chapter describes the implemented console foundation and customer management. The console foundation is deployed at app.drykraft.com/sa after bounded commercial acceptance, restricted-access checks and backup restoration checks. Each new staff account must complete its own authenticator setup before entering. Consumed meters/credits, remaining reseller operations, domain branding, reusable snapshots and approved support access remain separate unfinished release scope. The reseller commercial controls have separate acceptance and deployment evidence. The invitation mail extension has separate acceptance and deployment evidence. Those unfinished features are not available in the deployed foundation.'),
  ]],
  ['teams-locations','Teams & locations','Organize current workspace members into teams and offices without changing access.',[
    section('Create a team or location','Open Settings - Teams & locations. Owners and administrators can create and edit; every current workspace member can read. Choose Teams or Locations, search by name and filter Active, Archived or All. The directory shows25 items per page. Names are unique within each kind, ignoring case, including archives. A workspace supports500 teams and500 locations.'),
    section('Save useful details','For a location, save name, description, address, city, country and a valid IANA timezone such as Asia/Kolkata. That timezone is descriptive and does not change workspace reporting or Calendar availability. For a team, save name, purpose, optional active location and an optional current workspace member as lead. Choosing a lead automatically adds them to that team; changing the lead keeps the previous person as an ordinary member.'),
    section('Assign current teammates','Open the detail page, choose Add workspace member and save the assignment. Search and page through current member names. Remove from team or location removes only that assignment. Clear or change a team lead before removing them. Location assignments are direct: associating a team with an office does not automatically assign its people to that location. Group membership and leadership do not grant administration or record permissions, change workspace roles or consume extra seats. Removing someone through Team members also removes their group assignments and clears their leadership.'),
    section('Archive safely and handle conflicts','Archive keeps details and assignments readable. Restore before editing or assigning people again. Active teams must move or archive before their location can archive; restore the location before restoring an associated team. Changes use the current version. If someone changes the item while you edit, your input remains visible until you choose Reload saved details. After a timeout, check the saved item before retrying; after an uncertain create, check the directory. Archiving and restoring use saved details, so save any pending detail changes first.'),
  ]],
  ['templates','Editable templates','Create reusable invoice designs, expense defaults and outreach messages for your workspace.',[
    section('Create and edit reusable content','Open Templates from Settings, Finance or Outreach. Search by name and filter type or Active/Archived status. Create a named invoice, expense, email, SMS, AI voice or WhatsApp template. Save, reopen and edit it as needed. Owners, administrators and members can edit; viewers can inspect. Each save checks the current version. On a stale-edit error, your input remains visible; explicitly discard and reload to see the latest saved version.','Archive and save to hide a template from draft pickers. Uncheck Archive and save to restore it. There is no permanent-delete operation. The current library supports100 templates and2 MB per workspace. Templates are private to the selected company. Do not put provider credentials or customer lists into reusable content.'),
    section('Apply a template to a draft','Create or open a Draft invoice or expense, or an outreach campaign/sequence draft. Choose a saved template and press Apply template. It replaces only its content/default fields; review and save the draft. Outreach retains its wait, connected account and audience. Library changes do not update existing copies, issued invoices or launched campaign steps. Finance workflow templates already open as editable drafts in the shared automation builder.'),
    section('Customize invoice documents','Invoice templates control the document heading, customer/payment/notes labels, payment instructions, default notes, footer and divider color. The supplied logo and accurate status, invoice number, dates, amounts and financial labels remain in the PDF. Blank payment instructions use your issuer profile. Default notes are copied when you apply the template. Preview sample PDF uses a fictional customer and line item and does not create or issue an invoice. Actual saved PDFs use the validated document design stored with the invoice; issuing locks its details.'),
    section('Customize messages with provider boundaries','Email templates contain a subject and message, with CRM expressions such as {{record.data.name}}. Campaign sends format paragraphs, bullet lists and web links into an HTML email with a workspace header and unsubscribe footer; a plain-text alternative is included. Preview substitutes Sample customer for that example expression; other expressions remain visible and are resolved by the normal sending flow. Unsubscribe content is added automatically at send time. SMS templates contain message text or up to40 named text variables, mapped by the provider connection.','WhatsApp templates save an approved Meta template reference, language and editable body parameters. Change the source wording and obtain approval through Meta; DryKraft verifies availability and matching parameters before launch. AI voice templates save assistant and dialer IDs. Edit the script and voice in QCall; IDs are validated for the selected connection before launch. Saving, previewing or applying a template never sends or calls.'),
  ]],
  ['getting-started','Start a workspace','Create your account, set up the company and find your first useful workflow.',[
    section('Create your account, then your workspace','Open the application and choose Get started. Enter your name, email and a password of 10-128 characters. Signup creates the account first. The next onboarding step asks for company name, workspace address, default currency and enabled currencies. If setup is interrupted, sign in again to finish it.','An address starts with a letter and contains 3-40 lowercase letters, digits or hyphens. Names such as app, www, api and support are reserved. Availability is checked, but only successful workspace creation reserves the address. The 15-day free trial starts when the workspace is created, not when the account is created.'),
    section('Find the right module','The thin main menu switches between CRM, Sales, Finance, Outreach, Calendar, Automation and Settings. The second menu shows that module’s pages. CRM contains dashboards and customer records; Sales contains opportunities; Finance contains invoices, expenses and approvals. Outreach is where you connect communication providers and review campaigns or sequences.','Use the workspace switcher to select a company you belong to. A workspace has its own records, settings, roles and provider connections. Being a member of one company does not give access to another. Teams and locations organize people within that workspace.'),
    section('Make a small first workflow','Set currencies and timezone, add one person and a follow-up task, then configure a sales pipeline. Add real team members only after choosing their roles. Configure invoice issuer information before issuing documents. Review a workflow draft before publishing it. Connect an outreach provider and use a narrow consented smart list before launching anything.'),
    section('Workspace addresses and current hosting','The central application is available at app.drykraft.com. A chosen slug identifies your workspace. Workspace-subdomain routing is enabled on the current deployment, with wildcard DNS and HTTPS for *.drykraft.com. After sign-in, DryKraft opens the selected workspace address. Choosing an address does not create a custom domain, mailbox or website. Customer-owned domains are not supported in this release.'),
  ]],
  ['workspace-currencies','Workspace & currencies','Configure the company, timezone and supported denominations without changing historical amounts.',[
    section('Company settings','Owners and administrators can open Settings - Workspace to change the company name, timezone, default currency and enabled currencies. Select a valid IANA timezone, such as Asia/Kolkata. Save deliberately; the form does not autosave. Workspace address cannot be changed through this settings form.'),
    section('Default and enabled currencies','Choose USD, INR, EUR, KWD or another currency in the supported catalogue. The default must be enabled. Enable every denomination needed for new monetary records. Changing the default affects the initial choice for new records and default reports; it does not convert existing values. Disabling a currency prevents new records in that currency while existing records can retain it.'),
    section('Precision and reporting','Finance respects currency precision: USD, INR and EUR use two decimal places; KWD uses three; JPY uses none. Enter amounts in major units. Financial calculations and payment history store minor units to keep totals consistent. Monetary dashboard queries and pipeline totals keep currencies separate. There is no automatic foreign-exchange conversion or consolidated exchange-rate report.'),
    section('Audit and access','Settings - Audit trail shows the latest supported business and membership events to owners and administrators. Account password/session events have a separate private history in Security. Trial expiration preserves read access but requires an active subscription for most changes and automation.'),
  ]],
  ['developer-access','Developer access & API keys','Give integrations a separate identity with reviewed workspace permissions.',[
    section('Choose an integration identity','Open Settings - Developer access as an owner or administrator. A service account represents an integration, not a teammate: it cannot sign in to the application and does not consume a user seat. Choose a recognizable name and explicit current object permissions. Each object needs Read; Create, Update, Delete and Add notes can be added where supported. Read includes every field and owner for that object. Fine field/team/owner policies are not implied. Financial objects allow only Read and Add notes through this API.'),
    section('Review workflow identities','The Workflow accounts section lists one automatically created identity per immutable published version, including managed campaigns and WhatsApp AI versions. Open a version to review its native object actions and saved resource names. Owners/admins can reduce actions or disable it; restoring actions or enabling requires current password approval. Stale edits remain until you explicitly refresh. Workflow identities never receive API keys or consume integration-account limits.','The reviewed graph sets an immutable ceiling for native actions, step kinds, pinned child/error versions, saved credentials, calendars and outreach connections. Caller and error-source identities constrain downstream execution too. Read covers all fields/owners; finer field/team restrictions remain unfinished. Saved external resources retain their published authority and are not edited by the native-object checkboxes. Publish a reviewed version to change resources. Dynamic notes and event input can need read access to all objects present at publication; future objects are not granted automatically.','Disable blocks admission and further checked effects, including continuation after a Wait or recovery. In-flight native transactions can finish before the change saves. An external request already accepted cannot be recalled. Completed steps and history remain. Publishing a new reviewed version creates fresh access; restrictions on a historical version do not automatically carry over.'),
    section('Approve an expiring key','Approve creating an account, expanding access, enabling a disabled account, issuing a key or rotating one with your current password. Access approval is limited to 30 attempts per account per 15 minutes. Each key has its own permissions within the saved account ceiling and expires after 1-365 days. Accounts support up to ten active keys; workspaces support up to100 active service accounts. New objects receive no automatic permission.','A newly issued secret appears once. Keep it in your integration’s secret store, never in a website, browser bundle, URL, shared screenshot or source repository. List/detail/history responses contain only metadata and a public prefix. If the first response is lost, retrying the same reference returns the existing key with no secret; revoke that key and issue a replacement.'),
    section('Narrow, disable, rotate or revoke','Reducing account permissions permanently narrows existing keys. A later expansion does not silently restore them. Disabling the account blocks all its keys; enabling again requires password approval. Rotate issues a replacement and immediately revokes the old key; update the integration to use the one-time replacement. For a staged change, issue a separate key first and revoke the old one afterward.','Revocation and disablement wait for business transactions already using the key. Those can finish; future requests fail. Revoked keys and disabled accounts remain in history. API request history lists normalized operations/statuses and public integration names, with pagination and no customer payloads or credentials. Final history is asynchronous and can omit a row if the process exits before recording it; valid authenticated attempts are durably metered before dispatch.'),
    section('Use the versioned CRM API','Use Authorization: Bearer with the secret under https://app.drykraft.com/api/v1. Browser session cookies cannot replace a key here; keys cannot access browser, billing, workflow, provider or administrator endpoints. /me reports the current effective permissions; /objects shows authorized schemas. Contacts, companies, leads, opportunities and tasks have native collection aliases; /records/{key} also supports custom objects and financial reads.','Writes require a UUID Idempotency-Key, current permission and active trial/paid access. PATCH keeps omitted fields and requires the current record version. The same key/account/request reference retries without repeated records, notes or events. Reusing it with another path or payload conflicts. Preserve field order when retrying; the validated serialized JSON must match. Refresh after409. Archived contact references remain resolvable. Financial writes and deletion use Finance in the application. An external SDK and service-account workflow/provider administration remain outstanding.'),
    section('Subscribe to customer webhooks','The administrator session API under /api/developer/webhooks registers public HTTPS endpoints for selected business events. It is separate from incoming workflow, Dodo and Meta callback URLs. Read the current event catalogue, supply a stable creation UUID and approve with your current password. Open Settings - Webhooks, choose New webhook, enter the receiving URL and select events. Approve with your current password, then save the one-time signing secret privately. Open a subscription to change its configuration, rotate the secret or inspect delivery history. Use the Customer webhooks API reference for the administrator session contract. Up to 50 retained endpoints and 100 selected event types per endpoint are supported.','A committed business event and its pending delivery are stored together. Subscriptions receive future matching events only, including custom CRM objects currently in the catalogue. The immutable schema_version=1 envelope contains event ID/type, workspace ID, occurrence timestamp, resource type/ID and correlation/causation IDs. Customer fields, message text, emails and credentials are excluded. Use your separately scoped CRM key to fetch authorized current record details when needed.'),
    section('Verify signatures before processing','Every request is POST application/json with drykraft-webhook-id, drykraft-webhook-timestamp, drykraft-webhook-signature and Idempotency-Key. The delivery ID is stable across retries/replay; the envelope id is the business event ID. Signature format is v1= followed by lowercase hexadecimal HMAC-SHA256. The key is the UTF-8 one-time signing secret exactly as issued. Sign the UTF-8 delivery ID, a period, decimal Unix timestamp in seconds, another period, then the exact raw body bytes. Do not parse and reserialize JSON before verification.','At your receiver, enforce a five-minute timestamp window, validate header formats and use a timing-safe comparison of equal-length decoded digest bytes before trusting the payload. Keep a durable unique constraint on the delivery ID, including across retries and manual replay, and return a 2xx response only after accepting the work durably. A timeout or worker interruption can happen after your server has accepted the message. Signing alone does not prevent duplicated external effects.'),
    section('Handle retry, failure and replay','Any 2xx response completes delivery. Redirects are blocked, DNS is rechecked and pinned on every attempt, and private/reserved addresses are refused. HTTPS port 443 is required; user credentials, query parameters and URL fragments are prohibited. Attempts use the existing 20-second bounded HTTP transport. Failed attempts retry after 60 seconds, 5 minutes, 30 minutes and 2 hours; the fifth failure disables the endpoint and cancels its other pending deliveries. Expired billing defers delivery 15 minutes without consuming an attempt.','History lists 25 deliveries per page and the latest 50 completed attempts per delivery. Receiver bodies, raw network errors and signing values are never saved. A process loss after receiver acceptance can omit the completed attempt. Fix the receiver, reapprove enabling the endpoint, then replay a current failed delivery using a stable operation UUID and acknowledge_duplicate=true. Replay preserves the original destination, event/body and delivery ID, resets the five-attempt cycle and uses a fresh timestamp/current secret. Cancelled deliveries are not replayable. Disabling, removing a subscribed event or changing destination cancels its pending old deliveries; in-flight work may finish before the change completes.'),
    section('Rotate a webhook secret','Signing secrets are encrypted with the workspace-bound vault and shown only in the initial creation/rotation response. A completed retry returns secret=null. Rotation requires current password, current endpoint version and a new operation UUID. All subsequent deliveries and retries use the replacement secret immediately; the previous secret has no server-side grace period. Prepare the receiver to accept the replacement during a coordinated rotation, then remove the old verification key. If the one-time response is lost, rotate again rather than attempting to retrieve it. No real external receiver acceptance is implied by local contract tests.'),
  ]],
  ['crm-records','CRM records & follow-up','Use people, companies, leads and tasks with typed fields, relations and activity.',[
    section('People, companies and leads','Open a CRM record page and choose Add. Enter the required name and the fields your team needs. People hold email, international phone, company context, lifecycle, source, tags, owner and Marketing consent. Companies hold company details. Leads hold qualification status, source, score, owner and potential value. A free-text owner label is not a separate permission policy.','Open a record for details, notes and follow-up. Saved edits validate the object’s fields and required values. Concurrent changes are rejected; refresh the latest record before trying again. Searching a record page matches common name/contact/company fields, while global search matches record names.'),
    section('Enter Sales as soon as a lead is created','Saving a new lead atomically creates a linked contact and an Open Sales deal. Select an existing contact/company to reuse it; a matching contact email and an unambiguous company name are reused without overwriting their saved details. Otherwise a new contact/company is created. Marketing consent remains off for a new contact. Choose the required Sales details if your workspace has required custom deal fields. A failed required field, plan limit or missing related permission rolls back the entire save.','The deal uses the lead’s starting name, value, currency and owner, and the first stage other than Won in the first alphabetically listed pipeline. Later Sales prices, stages and status are maintained in Sales. Changing a lead’s contact/company updates the linked deal when that relationship has not been independently changed there. Use lead qualification status independently. Convert marks the lead Converted while retaining its linked contact and deal, so it does not create duplicate sales work. Already converted leads cannot be converted twice.'),
    section('Continue work from Related','Open a CRM or Sales record and choose Related. Finance records show the same connected work below their details. Open linked contacts, companies, leads, deals, financial records or custom objects by their saved names. Tasks use a searchable Related record picker, including custom/Finance objects. Relationship pickers search and page through all records, with a saved selection retained beyond the first page.','Choose Add task, Book appointment or Create invoice from the record. Tasks retain the source record. Appointments prefill the related contact’s name/email for review. Invoice drafts prefill customer, contact, company, deal, currency and a line item from the deal; review before saving or issuing. Related shows saved appointments, campaign enrollments and workflow runs associated with this record and its actual contacts/deals. It does not start a campaign, send a message, charge a customer or run a workflow. Issued documents and their customer/payment snapshots retain their original values after contact updates/merges.'),
    section('Tasks and activity','Create tasks with status To do, In progress or Done, priority, due date, owner and an optional related record. Add a note, call, email or meeting activity to a record to preserve context. These activity entries record work; they do not send email or place calls. Use Outreach for actual messages and calls.'),
    section('Merge two contacts','Owners and administrators can select exactly two People records and choose Merge contacts. Choose the remaining contact, compare conflicting field values and select which to keep. Empty fields fill from the other contact and tags combine. Marketing consent stays enabled only if both contacts already explicitly consent. Custom amount fields using different currencies must be aligned before merging.','Choose Review merge to see the final identity and the number of notes, relationships, financial records and active source follow-ups affected. Confirm merge only after checking those consequences. A changed contact, definition, relationship or note requires a fresh review; stale contact versions require closing the dialog and selecting again. The original source record and immutable merge history are retained, while active tables, reports, search and audiences show the remaining contact. Existing links and future relation/activity writes resolve to it.','Issued financial documents and payment history retain their original details. Draft relation links can move without changing customer or amount snapshots. Queued source follow-ups are cancelled; a request already submitted to a provider may still finish. There is no restore action. Contacts preserving merge history cannot be deleted. Imports still use their own email duplicate policy; they do not automatically merge records. The Contacts merged business event is available in the workflow builder and includes the remaining record and merge effects.'),
    section('Tables, exports and deletion','Adjust visible columns for the information you maintain. Use page search/status filters or a saved smart list. Pages use cursor pagination. Export the selected view through the available CSV control; exports preserve array values and neutralize spreadsheet formulas in text. There is no separate export API.','Delete only after confirming the record. Another record’s relation can block deletion; remove or correct that incoming relation first. Financial records use their dedicated Finance lifecycle rather than generic deletion. Deleted records have no restore interface in this release.'),
  ]],
  ['imports-smart-lists','CSV imports & smart lists','Validate customer imports, apply atomic bulk changes and keep audiences current.',[
    section('Prepare and review a CSV','Use UTF-8 CSV with a header row, up to 500 data rows and 300 KB. Open a nonfinancial record page, choose Import CSV, select the file and map each column to one field or Skip. Dates use YYYY-MM-DD, amounts use plain numbers and multi-value fields accept JSON arrays or semicolon-separated values. Include a currency code when importing monetary data.','Review validation for the whole file before applying. Invalid rows prevent the whole import; the preview shows a bounded sample and up to 20 errors. For People, choose skip, update or error for existing email addresses. Updates preserve existing values for blank CSV cells. Other objects create new records. Raw import files are not retained.'),
    section('Apply and change in bulk','Applying a valid import is transactional and retry-safe with the same operation reference and content. Keep your source file until checking the resulting records. Imports do not merge duplicate people, import financial documents or queue larger files.','Select records on a page, choose a shared field update or Delete, review and confirm. A batch contains at most 100 records. Current versions are checked and the whole batch fails if a record changed. Related records still protect deletion. Refresh and reselect instead of retrying stale versions.'),
    section('Create a dynamic smart list','Choose a nonfinancial object, open the smart-list editor, name the list, select Match all or Match any and add up to 12 typed conditions. Preview the matching records before saving. Text, tags, numbers, dates, selections and checkboxes support appropriate operators; JSON and relation fields cannot be filtered this way.','An amount comparison requires Match all and a Currency is condition. A saved list follows current records, rather than copying a fixed snapshot. Search and status filters intersect the saved list. You can create up to 100 lists per object. Members can edit; viewers can use lists but cannot change them.'),
    section('Edit, remove and reuse an audience','Refresh if someone changes a list before your save. Removing a list retains its records. Outreach campaigns and sequences can use these rules as their source audience; launch captures the reviewed eligible contacts. Later list changes do not silently enroll new people in an already launched campaign.'),
  ]],
  ['sales','Sales pipelines & deals','Track opportunities from a named stage to a won or lost decision.',[
    section('Configure stages','Owners and administrators configure pipelines and up to 30 stages. Give each stage a distinct ID/name, probability from 0-100 and color. Move deals to retained stages before removing a used stage. Pipeline probability is a configured field, not a forecast guarantee.'),
    section('Read the deal’s stage history','Open a saved deal from the board or list and choose Stage history. Read the latest transition, its saved from/to pipeline and stage names, actor and timestamp in the workspace timezone. Refresh for new changes or load older changes in pages of25. Read-only teammates can inspect it.','New deals record their initial stage. A saved change to stage or pipeline appends one entry through the shared record path, including imports, bulk updates, API integrations and workflows. Changes to other fields and rejected or retried writes do not invent transitions. Snapshot names remain after pipeline/stage renames; actor names reflect the current identity. Earlier moves are not reconstructed. History is removed with a deleted deal.'),
    section('Create and move an opportunity','Create a deal with name, company, related person, value/currency, pipeline and stage, status, expected close date and owner. Use the sales board or record editor to update the stage. When a pipeline is selected, its stage must belong to that pipeline. Open, Won and Lost are deal status values. Keep stage and status consistent with the actual decision.'),
    section('Follow through on won and lost deals','Mark a closed success Won and capture Lost reason where appropriate. A newly won deal emits an event that can start a published workflow, including a reviewed invoice draft template. Winning does not itself issue an invoice or collect payment. Pipeline totals separate denominations; use a dashboard for a specific currency question.'),
  ]],
  ['finance','Invoices, purchase orders, expenses & approvals','Create supplier orders, prepare customer invoices, approve spending and record payments.',[
    section('Set document numbering','Open Finance - Settings as an administrator. Save business name, email, address, tax reference, payment instructions, invoice prefix and purchase order prefix. Prefixes allow 1-12 uppercase letters, digits or hyphens; defaults are INV and PO. Issued documents keep a snapshot of the issuer used at issue, so later settings do not rewrite old PDFs.'),
    section('Draft and issue an invoice','In Invoices, create a draft with title, customer name/email, billing address, optional contact/deal, enabled currency, invoice date, due date and 1-100 line items. Each line has description, positive quantity, unit price, optional line discount amount and tax rate. Due date cannot precede issue date. Quantities allow three decimals; currency amounts use currency precision; tax percentage permits two decimals.','Save and review the draft. Issue assigns a unique number by prefix/year/sequence and freezes the document details. A positive total is required. Download the PDF and deliver it through your own process. Issuing does not email the invoice. An administrator can void an unpaid Draft/Issued invoice with a reason; paid or partially paid invoices cannot be voided here.'),
    section('Create and issue a purchase order','Open Finance - Purchase Orders and choose Create purchase order. Add a supplier or link a vendor company, optional deal, enabled currency, order and expected delivery dates, line items, discounts, tax and notes. Save the draft to make changes later or use Save and issue to assign a unique prefix/year/sequence number. Issued POs keep an issuer snapshot and can be downloaded as PDFs. Cancelling keeps the order in history with a reason; an administrator must cancel an issued order. A PO records an order commitment and does not pay the supplier or record an expense automatically.'),
    section('Record received payments','After receiving money externally, enter a unique payment reference, amount, received date and method. Dates cannot be future dates; amount cannot exceed the balance. Separate partial receipts move the invoice through Issued, Partially paid and Paid. Payment entries cannot be edited or deleted through the current API. Check the reference and amount before saving.','Finance Overview shows outstanding, collected, overdue and paid expense totals per currency. Overdue uses the workspace timezone. There is no bank feed, automatic reconciliation, customer payment checkout, credit-note/refund workflow or automatic invoice delivery in this release. Dodo bills your DryKraft subscription separately.'),
    section('Submit, approve and pay an expense','Create a Draft with title, vendor, date, currency, positive total amount, category, included tax, notes and optional receipt URL/deal. Included tax cannot exceed total. The receipt is a web reference, not an upload. Submit when ready for review. An owner/admin approves or rejects; rejection requires a reason. Reopen a Rejected expense to Draft to revise it.','Only an administrator can record payment for an Approved expense, for its exact full amount and actual paid date/reference. That changes it to Paid without initiating a transfer. Approvals shows submitted work. Use Finance workflows to create drafts/tasks from won deals, submissions or paid invoices; each template starts unpublished and needs review.'),
  ]],
  ['customization-dashboards','Custom objects, fields & dashboards','Shape records and KPIs around the questions your team needs to answer.',[
    section('Define objects and fields','Open Settings - Objects & fields as owner/admin. Add a field to an existing object or create a custom object with plural/singular names and a unique key. Keys start with a lowercase letter and contain 2-40 lowercase letters, digits or underscores. Each object has up to 100 fields.','Types include text, email, phone, number, currency, checkbox, date, single selection, multiple selection, relation and JSON. Selection options are bounded to 100. Relations must reference a record in this workspace and the required target object when configured. Currency fields need an associated currency-code field, added automatically when absent.'),
    section('Edit names and custom field rules','In Objects & fields, choose Edit names to rename an object’s plural and singular labels. Choose Edit beside a field to change its label. For custom fields you can also update choices, one per line, and the Required field rule. Leave choices empty to allow any value. Saved keys, field types and related objects stay fixed so records, APIs and workflows retain their identifiers. Built-in field rules are managed by DryKraft; their labels are editable.','Required fields cannot be added to an object that already contains records. Start with an optional field, populate all existing active records, then edit it to make it required. Removed choices must no longer be used by existing records. Changes reject invalid data and retain your input; on a conflicting edit choose Discard edits and reload to open the current definition again. Issued financial records keep their values and may prevent a new rule. Definition deletion, type conversion and fine-grained object/field/team permissions remain separate work.'),
    section('Assign a workspace member','Add an optional Workspace member field in Objects & fields, then open a CRM record or Finance draft. Search current members by name, choose one and save. Bulk updates and smart lists use the same picker. Copy member ID when preparing CSV imports or workflow/API values; names and email addresses are not accepted as assignments. Read-only members can be assigned without gaining write access. If someone leaves, their existing reference remains as Former member and can be kept when editing other details, cleared or reassigned; it cannot be copied to a new record. Current member names are shown in record tables; CSV exports retain IDs. Built-in Owner text fields remain unchanged. User grouping in dashboards currently uses stored IDs, not name-based identity.'),
section('Build a dashboard','Choose a dashboard or create one, then add and configure widgets. Choose the object, count/sum/average operation, numeric field for sum/average, optional filter/grouping and metric/bar/donut display. Customize exposes Edit on each widget; edit keeps its identity and position. Save up to30 widgets. Current version checks protect against overwriting a teammate’s configuration.','Use one currency for a monetary widget; counts and plain numeric fields can span denominations. Financial sums/averages require an explicit currency choice. Charts return up to100 result groups ordered by value and label. A KPI number has no grouping. Negative values can use a bar chart; a donut lists negative values instead of inventing slices. Its average display labels category averages rather than summing them into an overall average. Empty results display a zero Total. These are configured aggregate queries, not arbitrary SQL, formulas or external data sources.'),
    section('Choose the dates behind a KPI','Set a custom inclusive From/Through range or Today, Last7days, Last30days, This month or Last month. Last7/30days include today. Choose Record created, Record last updated or a date field from that object. Record timestamps use the current workspace timezone, including daylight-saving boundaries; stored date fields keep their calendar date. Rolling periods update whenever results are queried; fixed dates remain fixed. All time removes the date constraint.','Each widget keeps its own source and period, visible beneath its results. Changing the workspace timezone changes metadata-date interpretation and rolling boundaries. Changing a record’s update time can move it into another period.'),
    section('Download the current report','Choose Download report to get a UTF-8 CSV of the saved dashboard’s current aggregate results. Read-only teammates can download. The file includes widget/object/calculation, grouping, raw value, currency, exact filter, date source/resolved From/Through, workspace timezone and generated time. Text cells are escaped for spreadsheet formulas; currency values remain numeric with their code in a separate column.','This exports up to100 groups per widget and3000 rows, matching the configured result limits; it is not a full raw-record export. The server rechecks the dashboard version: refresh after a teammate changes it. Download queries current live records and can differ from older on-screen values. One clock resolves every rolling period, but this is not a frozen database-wide data snapshot. Empty dashboards download headings only. Scheduled report delivery, formulas, drag/resize and external data sources remain separate work.'),
  ]],
  ['automation','Workflow automation','Build a draft, publish a version and follow durable execution history.',[
    section('Create and publish','Open Automation - Workflows and create a named draft. Use one trigger and connected actions on the canvas. Save validates the graph shape; Publish as an administrator validates node settings and creates an immutable version, then activates it. Exactly one trigger is allowed, all nodes must connect to it and cycles are rejected. A condition may branch to unique true/false outputs. Switch routes the first matching case or its default, with one connection per output; other nodes have one outgoing path. Up to 100 nodes and 150 edges are supported.'),
    section('Edit and organize the canvas','Search the Add step picker by name or category. Shift-click steps or use Select steps for accessible multiple selection. Copy and Paste reuse action/logic steps and their internal connections with new IDs inside this workflow; the one trigger stays in place. Connect pasted steps before publishing. Copying a complete group also copies its label and membership. The clipboard stays only in this editor session and never uses the system clipboard or crosses workspaces.','Group selected steps, rename a group, drag its heading to move its members together, or ungroup without changing execution paths. Up to 50 non-nested groups are saved with the draft and published version. Undo/Redo restore up to 50 draft edits, including connections, grouping and removals. Typing or a drag gesture uses one history item. Ctrl/Cmd+Z, Shift+Z or Y, C and V work outside text fields; text fields retain their native shortcuts. Saving keeps session history; leaving/reloading clears it. Undo past a saved draft marks it unsaved again. Published executions remain unchanged.'),
    section('Triggers and actions','Triggers are manual, business event, interval/calendar schedule or webhook. Elapsed intervals are 1-525,600 minutes. Calendar schedules use five-field cron and a named IANA timezone saved in the published version. Presets include daily, weekday and Monday 9 AM; custom expressions are supported. Preview the next five times before publishing. Changes clear the previous preview. Preview does not run actions. Publishing or reactivation starts from the next future time. After downtime one overdue occurrence queues, and other missed times are skipped. Around daylight saving transitions, a skipped daily clock time shifts forward and a repeated daily clock time runs once; use the preview to review the actual dates. Wait pauses for 1-2,592,000 seconds and persists state instead of keeping a worker open. Conditions support equality, inequality, numeric comparisons, contains and exists. Set adds values to context; log records output.','CRM create/update validates the same record schemas and relations as the app. New lead creation also creates its linked contact/company and Sales deal; fresh publications derive the related native grants. Existing immutable workflow identities retain their approved ceiling, so republish a lead-creation workflow to authorize the additional writes. Reduced grants still fail closed. Finance create makes only a draft. HTTP uses a public destination and stored credentials; private/local destinations and unsafe redirects are blocked. Use the credential vault for bearer/basic/custom-header values. These are outbound provider credentials, not API keys for DryKraft.'),
    section('Reuse a workflow with typed inputs and outputs','Create a workflow and change its trigger to Sub-workflow trigger. Define Input fields and Output fields as JSON objects, for example {"name":{"type":"string"},"amount":{"type":"number"}}. Supported top-level types are string, number, boolean, object and array. Fields are required and non-null unless required:false or nullable:true is set. Up to50 fields per contract; undeclared values are rejected. Names start with a letter and use letters/numbers/underscores, up to60 characters. Inputs cannot use nodes, last, today, dueIn30Days, item, index or loop. Nested object/array properties are not schema-validated.','End every child path with Return values mapped to the declared output fields. Connect all Condition/Switch branches; Return values belong outside Loop item paths, after Completed. Inputs and returned objects allow256KB each. Test with typed trigger input, then publish the child. In a parent workflow add Call sub-workflow, search published names, select a version and map only its input fields. Exact expressions retain JSON types. Publication pins that immutable version, checks this workspace and active child, and rejects self/ancestor calls. Later child drafts/publications do not change existing callers.','The parent waits without occupying a worker. The child runs on the same durable fleet and releases its own worker during Waits. The parent checks the saved child about every two seconds. Output contains execution_id, workflow_id, version_id, version and output; use {{last.output.amount}} in the next step. Open child run from its execution card; child details link back to the parent. Each Loop item has its own child binding. Five call levels and1000 children per root execution are enforced. Each successful child and parent records its own workflow usage entry.','Failed/cancelled children stop the parent step; automatic retries reuse the same child rather than rerunning it. Review and retry a failed child, then continue the failed parent. A cancelled child cannot be retried; deliberately rerun the parent if the work should start again. A full child rerun is blocked: rerun its parent to establish a new binding. Completed child results are reused on recovery. Pausing a child prevents new calls but does not cancel bound runs. Cancelling a parent stops pending descendants; work already accepted cannot be undone. Billing checks apply separately to every run. Finer workflow service identities remain unfinished.'),
    section('Handle a failed workflow','Create and publish a workflow with an Error trigger. Its steps can record an internal task, transform failure data or call a reusable workflow. On the source workflow, select its trigger, search Find an error workflow and choose Error workflow. Save and publish the source. The exact selected immutable handler version stays pinned across newer handler publications. Only active published handlers in this workspace are selectable; up to200 matching names are shown.', 'After automatic retries are exhausted, source failure and one handler execution are saved in the same transaction. The handler receives failure.execution_id, workflow_id, version_id, node_id, iteration_path, attempts, message (up to2000 characters) and failed_at. It does not receive the source input or context. Use {{failure.message}} and {{failure.execution_id}} in its steps. Open error handler from source details and Open failed run from handler details.', 'One automatic handler is queued per source execution. Continuing or replaying that same source retains its handler, even if it fails again. A deliberate full source rerun creates a new execution and can create a new handler. Cancellation does not invoke a handler. Paused/unavailable handlers and inactive workspace plans leave an explicit skipped reason; reactivation does not backfill that skipped handler. Handler runs and their called children cannot recursively start automatic handlers. Error workflows cannot be started by Test run; test their source workflow instead. Recover a failed handler using the existing reviewed controls. Actions follow their ordinary validation, billing and tenant rules; finer service-identity permissions remain unfinished.'),
    section('Transform CSV content','Add CSV in the workflow editor. Choose Parse CSV and enter a plain source path such as csv or last.body. Use comma-separated UTF-8 text with distinct headings, quoted values and escaped quotes; a leading BOM and multiline cells are accepted. Output has items, headers and count. Every cell remains text, including numbers and dates. Blank rows are skipped, and a valid headings-only document returns an empty list. Use Map list or Set values before later actions to shape the records.','Choose Create CSV to turn an array of record objects into text. Enter a source path such as last.items, then list exact field names one per line in output order. Use up to100 distinct names without surrounding spaces or prototype keys. Missing/null fields become empty cells, objects/arrays become JSON text, and finite numbers remain numeric text. Text starting with spreadsheet formula characters receives an apostrophe; that safety change is retained when parsing the export again. Output has csv, headers and count; an empty array produces headings only.','Both operations support up to1000 rows and256KiB input/output, including JSON expansion. Malformed rows, duplicate headings, unsafe names or excess size stop the step before the next action. Saved successful transformations are reused during recovery; full reruns evaluate the source again. This transforms text within the shared runtime, without uploading/downloading files or importing CRM records. File/storage nodes and streamed large files remain separate work.'),
    section('Split and merge workflow paths','Add Split and name two to ten branches. Use the named path selectors or canvas handles to connect every branch to its own steps. Add Merge, choose its paired Split and connect the end of every branch to it. Exactly one Merge belongs to each Split. Branch steps stay separate until that Merge; every Condition or Switch output inside a branch must be connected. Nested Splits and Loops are supported, up to five combined levels. Loop item paths must finish before following their Completed route to Merge. Return values belong after Merge.','Every named branch runs in configured order under one execution lease. Each starts with an isolated copy of the saved Split context; root Set values do not leak into later branches. Use {{branch.label}}, {{branch.number}} or the zero-based {{branch.index}} inside a path. Step outputs are available by nodes.stepId after Merge. Collect outputs puts each branch’s final output into last.items. Append lists requires an items array from every branch and concatenates them in branch order, up to 1,000 total items. Output includes count and branches with id, label and output. Downstream steps run once after every branch finishes. No matching-key join or currency conversion is implied.','Waits release the worker. Persisted scope paths distinguish branch steps and Loop items during retry/replay; completed native actions and their saved outputs are reused. Cancellation stops later paths. A full rerun creates a new execution and can repeat effects. Limits are 10,000 visited steps, 256 KiB collected Split output, 256 KiB Merge output including its named branch results, and 1 MB control state. Large results can fail after actions have saved; finish each branch with only needed fields. Copying a complete Split/Merge group remaps its pairing; a copied Merge without its Split must choose a new pair before publication.'),
    section('Transform XML content','Add XML in the workflow editor. Choose Parse XML and enter a plain source path such as xml or last.body. Supply one well-formed XML1.0 UTF-8 document. Output exposes document, root and elements. The ordered document tree keeps qualified names and namespace declarations, attributes, repeated siblings, mixed text, CDATA, comments and processing instructions. Text and attribute values stay strings. XML standard line-ending and attribute normalization applies; numeric text is not coerced. DTDs, custom entities and external entities are refused; predefined and numeric references are decoded without file/network lookup.','Choose Create XML with a source such as last.document. Each document has type document and a children array, with optional boolean standalone. Elements have type element, name, an attributes array of name/value pairs, and ordered children. Text, cdata and comment nodes have type and string value; instruction nodes also have name. For example: {"type":"document","children":[{"type":"element","name":"customer","attributes":[],"children":[{"type":"text","value":"Sample customer"}]}]}. Use Set values to shape this JSON or pass a parsed tree directly. Creation emits a UTF-8 XML declaration, escapes text/attributes and validates namespace bindings and the single root. It preserves document meaning, not original quote style, empty-tag syntax or entity spelling. Output has xml, root and elements.','Both operations support 1,000 elements, 32 element levels, 5,000 content nodes, 100 attributes per element, 256-character names and 256 KiB input/output including JSON expansion. Bad names, namespaces, duplicate attributes, malformed comments/instructions, invalid characters or excess size stop the step before downstream work. Saved successful output is reused during recovery; full reruns transform the source again. This transforms context data and does not create files or dispatch network requests. File/storage and larger streamed processing remain separate work.'),
    section('Request a GraphQL API','Add GraphQL request. Enter a public HTTP or HTTPS endpoint on a standard port and a nonempty document of up to 64 KB. The document is sent as written; put context values into the Variables JSON object, such as {"id":"{{record.id}}"}, instead of inserting them into query syntax. Exact expressions retain numbers, booleans, arrays, objects and null. Variables are limited to 256 KB before and after resolution. Use Operation name when a document has multiple named operations. The destination validates GraphQL syntax and its schema.','Choose a saved bearer, basic or custom-header credential from Automation - Credentials. An administrator publishes the immutable version; publication checks that the credential currently belongs to this workspace, and the worker rechecks it before sending. Do not put private credentials in documents, variables or URLs. The step uses JSON POST and accepts GraphQL/legacy JSON responses through the existing protected HTTP transport. Private/reserved destinations and redirects are blocked, DNS is pinned per request, the request limit is 20 seconds and the response limit is 1 MB.','Output contains status and body. Use {{last.body.data.customer.id}} or {{nodes.<step-id>.body.data.customer.id}} to chain returned data. Stop this step is the default: GraphQL errors fail even with HTTP 200. Continue with partial data requires a nonnull data object, returns its errors/extensions and lets the next step inspect them. Errors-only, null data with errors, invalid JSON/envelopes and HTTP failures still fail. Failure text contains an error count rather than provider error messages; inspect the destination when troubleshooting.','Successful output is retained on continuation/replay. The existing automatic retry rules also apply to mutations. A stable execution/step/item idempotency key is sent; the destination must honor it to prevent repeated accepted changes. Review duplicate protection before publishing mutations and check ambiguous outcomes before retrying. No subscriptions, streaming, uploads, automatic pagination, introspection builder or local schema validator is provided.'),
    section('Run isolated JavaScript or Python','Add Code under Data. Select JavaScript or Python and a plain JSON input path such as last or nodes.searchStep.items, without expression braces. JavaScript runs an async function body with input and secrets arguments; for example return {value: input};. Python runs the body of main(input, secrets); for example return {"value": input}. Include return, not a complete function declaration. Changing language preserves the saved source, so update its syntax yourself. Return JSON; console/stdout output is unsupported. The value becomes last and nodes.stepId.','Every invocation uses a fresh nonroot gVisor container, with no host mounts or network, read-only image files and 16 MiB temporary space removed afterwards. Fixed official interpreter image digests provide standard libraries only; customer package installation is unavailable. Limits are 65,536 UTF-8 source bytes, 256 KiB JSON input/output, 40 JSON levels, 256 MiB memory, half a CPU, 32 processes and a selected 1-10 second execution deadline including normal startup; platform setup and cleanup have separate bounded waits and can add wall-clock time. Oversized/nonfinite/reserved-key output, console output, syntax errors and timeouts fail explicitly before downstream work. The API and ordinary workers never evaluate code. If the runner is stopped or busy, the step fails closed and uses ordinary bounded retries.','Expand Optional secrets to bind up to eight named saved credential values. Owners/admins choose aliases and current-workspace references; publication and runtime recheck ownership. Only the named values are sent through the private Unix socket, not application environment or other vault entries. Exact known secret strings are redacted before persistence and downstream context. This is not a general data-loss prevention system: code can encode or transform a secret, and returned data is visible to teammates with execution access. Administrators must review code and its input/output before publishing. Container stderr is discarded and failure messages do not echo program exceptions.','Completed output survives Wait, duplicate dispatch and recovery; a deliberate full rerun executes code again. Cancellation checks execution and ancestor state about every250ms, closes the runner request and removes its container before freeing the slot. Cancelling cannot undo previous actions. This server allows two active code jobs and one per workspace; a busy step uses the shared queue retry policy. Stop the isolated runner service for the operational kill switch. Independent sandbox fleets, broader package policies and finer workflow service identities remain separate work.'),

    section('Prepare dates and times','Add Date/Time and choose Current time, Format a date, Shift a date or Difference between dates. Dates accept YYYY-MM-DD at midnight UTC or ISO timestamps with an explicit Z/offset. Ambiguous clock times and impossible dates are rejected. Use context expressions such as {{today}} or {{nodes.<step-id>.iso}}. Current time is captured when the step first succeeds; recovery reuses that saved value.','For shift, positive amounts add and negative subtract. Exact amount expressions must resolve to finite JSON numbers, not text; magnitude is at most 1,000,000. Milliseconds/seconds/minutes/hours/days/weeks are elapsed durations; a day means 24 hours. Month/year shifts need whole numbers and use the UTC calendar, clamping to its last valid day. These operations do not preserve local wall-clock appointments across daylight-saving changes. Difference is End minus Start in elapsed units and can be negative; variable-length months/years are not difference units.','Choose a supported language code and IANA display timezone, such as en-GB and Asia/Kolkata. They change formatted display without reinterpreting input offsets. Output includes iso (UTC timestamp), date and time (in display timezone), formatted, timezone, locale and timestamp (Unix milliseconds). Difference output contains difference, unit, start_iso and end_iso. Use ISO to chain operations; the formatted text is for display. Years 0001 through 9999 only. No custom format pattern or implicit parsing of regional dates.'),
    section('Search CRM records','Add Search records and choose any current CRM/custom/Finance object. Enter optional name, email or customer search text and, for nonfinancial objects, an optional smart list. The smart list uses its current saved rules when the step runs. Search text intersects those rules; blank text searches all matching records. Choose Maximum records from 1 to 100, default 25. Search never changes records.','Output contains items, count for this page, total for all matches and next_cursor. No matches succeeds with an empty list, count/total zero and no cursor. Use last.items in a following list step, or {{nodes.<search-id>.items.0.id}} to reference a particular record. For another page add Search records with the same object/text/rules and {{nodes.<search-id>.next_cursor}}; an empty cursor starts at the first page, so use a Condition to avoid repeating when no cursor remains. Pages are newest-created first, with stable ID ordering; ongoing data changes can change later matches.','Advanced API-authored field rules use the shared typed RecordFilter schema and may reference exact context expressions for numeric, boolean, date, select or member-ID values. Publish validates fields/operators and current object/list ownership; run validates resolved values. Monetary rules require Match all and a Currency is rule. Output is capped at 256 KB and fails explicitly if too large; reduce Maximum records. Completed search output is saved atomically and reused on continuation/retry, rather than re-querying changed data. Later actions run once per page. To act on each found record, follow Search with Loop using last.items, then use {{item.id}} and {{item.data.name}} in its item steps. Fine workflow service-identity policies and parallel fan-out remain unfinished.'),
    section('Route by ordered cases','Add Switch and configure 1-10 ordered cases with names, context paths and comparisons. First match wins, including when several cases match. Default runs when no case matches. Use each named path selector or canvas handle to connect an action; an unconnected chosen path ends the run. Removing a case removes its outgoing connection from the draft. Published versions retain their original cases/connections.','Equality compares original types. Numeric comparisons use numeric conversion, matching Condition behavior; Contains requires text, Has a value rejects missing/null/empty text. Context expressions supply original typed values. The saved Switch output includes branch and matched; recovery uses that saved branch rather than routing again from changed context.'),
    section('Shape a list before the next action','Add Filter list, Map list, Sort list, Limit list, Deduplicate list or Aggregate list. List source is a context path containing a JSON array, such as items from test input or last.items from a preceding step. Each output contains items, count and input_count. Within settings/templates use item, item.name and index for the current list item; exact {{item.score}} expressions preserve numbers. Filter reuses condition comparisons. Map emits one object per item from the field template.','Sort uses a single text, boolean or finite-number key and asc/desc direction, with stable ties and missing/null values last. Deduplicate retains the first occurrence of each typed scalar key; missing/null keys form one bucket. Limit skips an offset then keeps the requested count. Aggregation provides count/sum/average/minimum/maximum with optional scalar grouping. Numeric measures require finite JSON numbers, not numeric strings. Results contain group, count and value; empty ungrouped counts/sums are zero and averages/min/max are null. Grouped empty input returns no groups. Text ordering is lexical; dates sort correctly when represented consistently as ISO text.','Each step accepts up to 1,000 input items and 256 KB JSON output; aggregation allows 100 groups. Larger inputs fail explicitly. Aggregation uses ordinary JSON numbers and does not convert currencies or provide exact financial accounting. List steps do not execute downstream actions separately for every item; use Loop for per-item actions. Parallel branch execution remains separate work. List steps do not execute user code; use the separate isolated Code step for JavaScript or Python. Inspect saved node output and reference {{nodes.<step-id>.items.0.value}} when later steps replace last.'),
    section('Run actions for each list item','Choose Loop and enter a plain List source path such as items, last.items or nodes.<search-step-id>.items, without expression braces. Connect Each item to its action steps. End each item path with Finish current item; do not draw a cycle back to the Loop. Keep item steps separate from the Completed path. Condition and Switch branches inside an item may finish separately. Completed runs once after every item, or immediately for an empty list.','Inside the item path, {{item}} keeps the actual JSON value; {{item.data.name}} reads a searched CRM record. index is zero-based; loop.number starts at one, and loop.total/first/last describe the current list. Each item starts with the saved pre-Loop context. Set values and intermediate node outputs from one item do not leak to the next or outside the Loop. A nested Loop restores its parent item when Completed runs. Final output contains items (each selected terminal output in input order), count and input_count; use {{nodes.<loop-step-id>.items}} after later steps replace last. Finish item paths with Set values to collect a small useful result, such as record ID and name.','Input is snapshotted on entry. Up to 1,000 items, five nested Loops or Splits, 10,000 visited steps per execution, 256 KB input/collected output per Loop and 1 MB saved control state. The worker yields after 100 visits, persists the cursor and resumes through the existing queue. Waits release its slot. Excess output or control state fails explicitly; already completed actions remain saved. There is no parallel fan-out or automatic large-input batching.','Execution details label every visited item and nested item separately. Replay selects only the current failed step and its exact saved item path; completed native record actions retain their outputs. Continue also covers a saved native action whose following cursor write failed. Full rerun deliberately repeats actions. HTTP requests have a distinct stable idempotency key per item; the destination must honor it. Cancelling stops future items but cannot undo completed or accepted actions. No guarantee about actual provider delivery follows from saving a cursor.'),
    section('Expressions and event data','Use {{record.data.name}} to insert a field from an event record, {{record.id}} for its ID, and context paths from preceding work where available. Exact path expressions retain the original JSON type, including null; expressions inside text become text. Finance templates also supply today and dueIn30Days. Missing paths resolve to an empty string. Check a run’s node input/output rather than assuming a value exists.','Record changes use crm.<object>.created/updated/deleted; a newly won deal also emits crm.deals.won. A saved stage/pipeline transition emits crm.deals.stage_changed with record, from_stage, to_stage and stage_history_id; creation uses the normal created event. Use {{to_stage.stage_id}} or {{from_stage.pipeline_id}} in conditions, for example. Finance emits invoice/expense creation/update and state/payment events. Team invitations and member lifecycle emit workspace events. Audit and event dispatch share committed business changes.'),
    section('Assign owners and teammates','Built-in People, Companies, Leads, Deals and Tasks include Assigned owner, which stores a current workspace user ID. Existing free-text Owner values remain unchanged as Owner reference; customized labels are preserved. These references are history, not inferred member identities. Use the shared member picker in record details, CSV/API UUIDs or bulk editing. Smart lists use typed user equality filters and record tables show current member names or Former member for departed assignments. Changing unrelated data preserves departed history; creating or reassigning requires current membership.','Choose Assign owner in a workflow, then source Object, Record ID, Assignment field and Assign member or Clear assignment. Select a workspace member using paginated name search or use an exact context expression resolving to a user UUID. Names and email addresses are not IDs. This action supports existing user fields on nonfinancial CRM/custom records; Finance retains its lifecycle controls. Required fields cannot be cleared. Static publication checks and runtime rechecks enforce workspace membership and canonical source aliases. An unchanged assignment preserves version and events. Output contains record, field, before, after and changed; mutation/event/succeeded output commit together and recovery reuses saved output. Shared existing-record user-field changes emit crm.assignment.changed and are available in workflow triggers and customer webhooks. Initial creation retains its normal event. Finer owner/team/field permissions remain unfinished.'),
    section('Link records','Choose Link records, a nonfinancial source object and an existing relation field. Record ID identifies the source; Linked record ID identifies the target. Each accepts a UUID or exact safe plain context expression, including UUID step IDs. Set relationship validates the target object defined by the field, or any current-workspace object when the field has no target restriction. Clear relationship removes only that field; required relationships cannot be cleared. Merged contacts resolve to their remaining contact. All ordinary CRM writes share relation validation and existing-record changes emit crm.relationship.changed with record, field, before, after and configured target_object. Creation keeps its normal event. A repeated unchanged relationship preserves record version and emits no delta. Output contains record, field, before, after and changed. Mutation/event/succeeded output commit together; continuation and recovery reuse completed output. Full rerun re-evaluates against current data. Financial source relationships remain governed by Finance. Finer workflow service identity and permissions remain separate requirements.'),
    section('Move a deal stage','Choose Move deal stage and enter a Deals record UUID or exact context expression. Choose a workspace destination pipeline and one of its stages, or use exact context expressions for pipeline and stage IDs. Keep current status is the default; Open, Won and Lost are explicit choices. A stage move applies the destination stage probability, while a status-only change preserves probability. Repeating the same destination and status makes no update. Static targets are validated before publication; resolved values, current pipeline stages and workspace ownership are checked at execution.','Output includes record, before, after and changed. Before/after contain saved pipeline/stage names, status and probability. The shared record path records stage history and crm.deals.stage_changed for actual position changes; setting status to Won emits crm.deals.won on its transition. Stage names do not silently choose status. Mutation, events and succeeded output commit together; recovery reuses completed output. A full rerun acts on the then-current deal. Pipeline changes and record writes serialize stage membership validation. Fine workflow service identities remain separate work.'),
    section('Change contact tags','Choose Change contact tags, enter a People Contact ID as a UUID or exact context expression, then choose Add tags or Remove tags. Enter one tag per line, an array of tag templates in workflow JSON, or an exact context expression resolving to a text array. Context values in individual names are supported. Names are trimmed and case-sensitive; each resolved name has at most 80 characters and a contact can hold up to 100 tags. Static targets are checked on publication and current workspace ownership and resolved types are checked at runtime. Merged contacts resolve to their remaining contact.','Other tags stay in place. Adding only existing tags or removing only missing tags creates no record update or tag event. Output contains record, before, after, added, removed and changed. Mutation, event and completed output commit together; recovery keeps saved output. Contact tags changed is available as a workflow trigger and customer webhook event: crm.people.tags_changed includes record and these before/after/added/removed lists. Normal edits, imports, bulk updates, merges, versioned API and workflow writes share this event when existing contact tags actually change. Creating a contact uses its normal created event. Fine workflow service identities remain separate work.'),
    section('Add an internal CRM note','Choose Add note, enter a Record ID as a UUID or exact context expression such as {{record.id}}, and write the plain-text Note. Text can include context values such as {{record.data.name}}. Static IDs are checked when publishing; resolved values and record ownership are checked when running. Blank resolved notes, nontext exact values and notes over 10,000 characters fail visibly. Merged contacts resolve to the remaining contact. This supports CRM, custom and Finance records without sending an email or other message.','The saved output contains the activity ID, canonical record_id, body, type note and created_at. Open the record activity timeline to review it. Workflow notes use system attribution. Note creation, its event and step completion commit together; continuation/recovery retains completed output without adding the note again. A deliberate full rerun starts a new execution and creates another note. Fine workflow service identities and permission rules remain separate requirements.'),
    section('Runs, pauses and recovery','Run uses the published version, not unsaved draft changes. Execution history shows queued, running, waiting, retrying, succeeded, failed or cancelled. Open a run to see its saved version number, original input and current state/output/error per visited step. Retries update the step row; this is not a complete attempt-by-attempt timeline. Pause stops future triggering; existing execution control is separate. Cancel an unfinished run to stop further work, but an already accepted external side effect cannot be recalled.','Workers use Redis queues and PostgreSQL state for dispatch/recovery; CRM step mutation and completion commit together to avoid duplicate completed work. There is a bounded event chain depth of 16. Published versions stay immutable. Managed Outreach campaigns/AI workflows are controlled from Outreach and cannot be bypassed through this general editor.'),
    section('Replay a failed step or repeat the full run','A failed run offers Review replay on its current failed step. If no step has a failed row, such as a stop at the billing check or a recovered position, use Review continuation after resolving the reported problem. Continue execution retains the same version, input, context and completed outputs. Review failed-step replay continues that same execution with saved context and original input; completed steps retain their outputs. It cannot rewind a successful step or edit the input. HTTP retains the same execution/step idempotency key, but the destination must support it. If the error concerns invalid original data or node configuration, create a corrected published version and use a new test run instead.','A finished, failed or cancelled general run offers Review full rerun. It creates a new linked execution from the original published version and input, starting at its trigger. Later draft edits or newer publication are not used. Pausing future triggers does not prevent this deliberate manual rerun. Read the original input and acknowledge that records or external actions can repeat before Start full rerun. Inspect the provider first when acceptance is uncertain; a new execution uses new HTTP idempotency keys.','Recovery history shows the latest 50 linked requests, actor and time. View rerun/View original execution opens the related run. The details refresh while visible. Recovery requests use a stable UUID so an identical retry after an ambiguous response does not dispatch again; changing its mode, source or step conflicts. Existing write permission and active billing are required. Managed campaign/WhatsApp AI runs expose Outreach controls instead. Arbitrary successful-step replay and input replacement remain separate work.'),
    section('Incoming webhook','Create or rotate the workflow hook URL as admin, configure a webhook trigger and publish/activate it. The URL token authorizes execution; keep it private. POST a JSON object. Supply Idempotency-Key for safe retries of identical payloads; the same key with different data is rejected. Rotating the token invalidates the previous URL. Hooks accept at most 512 KB and share the auth/hook limit of 30 requests per 15 minutes.'),
  ]],
  ['calendar','Calendar & booking','Plan customer appointments, share availability and connect your own calendars.',[
    section('Start with availability','Open Calendar - Availability as an owner or administrator. Create a personal calendar with one host, or a team/service calendar with up to 20 current members. Round robin assigns the next available host; All hosts requires everyone to be free. Configure the named timezone, duration of 15-240 minutes in 15-minute steps, up to four working windows per weekday, and up to 100 date overrides. An empty override closes that date.','Notice can be 0-10,080 minutes, horizon 1-90 days and buffers 0-120 minutes before/after. Calendars are capped at 100 per workspace. Disable a calendar to stop new bookings without deleting its history. Existing appointment host/time/location snapshots stay fixed when settings change. Settings use current versions; refresh deliberately after a conflict.'),
    section('Use Month or Agenda','Calendar opens in Month view. Change the month, jump to Today and filter by calendar/timezone. Select a date for its agenda; open an appointment for details. On phones the complete month shows date/count buttons and the selected-day agenda below. Agenda lists the current month chronologically. Lists contain up to 1,000 appointments within a date range of at most 62 days; narrow by calendar if more exist.'),
    section('Book and manage an appointment','Choose New appointment, calendar, title, guest name/email and optional linked CRM record. Available times check working hours, overrides, notice, horizon, buffers, local bookings across every calendar and fresh provider availability. Internal users can choose a time outside working hours, with conflicts and provider freshness still enforced. Repeated daylight-saving clock times show separate offsets; nonexistent times must be corrected.','Save creates a persisted booking and its append-only history. A stable request UUID makes a lost-response creation retry safe. Open the appointment to edit notes, reschedule, cancel or mark Completed/No-show after its start. Closed appointments cannot reopen. Changes require the latest version. Cancellation is available after plan expiry. Linked records gain meeting activity; appointment lifecycle events can start workflows. Download Add to calendar for a UTC ICS file; this does not send an invitation.'),
    section('Publish and share a booking link','Public booking is disabled by default. Enable it in the calendar’s Booking access settings, then open Booking links to copy or preview its address. The public page exposes workspace/calendar name, description, location, duration and available times, never host names or guest lists. Keep description/location suitable for public sharing. Anyone with the link can book within the configured availability.','Guests choose their own timezone, date and slot, then enter name/email. Confirmation provides a private management link and ICS download. Save this link: it exposes the guest appointment and allows rescheduling/cancellation without signing in. No confirmation email is automatically sent. Disabling public booking prevents new appointments/reschedules; existing private links still allow viewing and cancellation. Public requests are capped at 120/minute/IP and booking mutations at 15/15 minutes/IP.'),
    section('Connect Google and Outlook','Open Calendar - Connections and copy the callback shown for the provider. Add the exact full URL to its OAuth client’s authorized redirect URIs. The default paths are /api/calendar/oauth/google/callback and /api/calendar/oauth/microsoft/callback; a configured Google callback can use a separate origin or the shared Outreach callback. For Google, use Google Cloud Console - APIs & Services - Credentials - the OAuth 2.0 Client ID configured on the server, and enable Google Calendar API. Use the frontend host configured in APP_ORIGIN when signing in. Google Calendar can share the Outreach callback configured in GOOGLE_OAUTH_REDIRECT_URI; GOOGLE_CALENDAR_REDIRECT_URI selects a separate Calendar callback. The initiating account/session must finish its own grant. Each user may retain up to 10 connections per workspace. OAuth creates a paused connection; choose an editable provider calendar before enabling busy imports or appointment exports.','Busy sync stores event times/IDs rather than outside event titles or attendees. Recurring events expand within 31 days before to 92 days after today, capped at 2,000 events/eight pages. Background sync runs about every five minutes; availability older than 10 minutes or outside a verified range blocks that connected host. Sync now refreshes the range. A provider failure does not silently declare the host free. Pausing a connection removes its availability requirement and leaves provider events intact.'),
    section('Understand appointment exports and conflicts','Optional export writes DryKraft appointment titles, times and locations to your chosen calendar; guest lists and internal notes are excluded, and no attendee invitations are requested. It updates events DryKraft created, rather than importing provider edits into local appointments. Up to 20 pending exports are processed per sync pass. Closed appointments become free events. A selected provider calendar cannot change after exports exist; add another connection instead.','Provider changes freeze the mapped export as Conflict. Review the provider event and appointment, then explicitly approve Use DryKraft values with the current appointment version. Ambiguous acceptance remains Unknown until sync recovers its matching provider marker; a new event is never blindly created again. An in-flight request may finish after Pause. Account grants, callback configuration and actual provider acceptance require separate live verification; injected-transport checks are not proof of a live grant.'),
    section('Connect reminders and attendance to workflows','Calendar emits Appointment created, updated, rescheduled, cancelled, completed, no-show and reminder-due events. Configure up to three reminder offsets; the UI offers 15 minutes, 1 hour, 1 day or all three. Reminders are durable events, checked about once per minute, not automatic emails/messages. Build a published event workflow that creates a task or uses a reviewed provider action. Notes-only edits do not repeat emitted reminders; rescheduling cancels pending old reminders and creates new ones. Past/closed/inactive-plan reminders cancel.','Book appointment is a shared workflow action. Select a current enabled calendar and provide title, guest_name, guest_email, starts_at with UTC offset and timezone; record_id/notes/outside_hours are optional. It uses the same availability checks and commits appointment creation with node completion to prevent duplicate bookings on retries. Appointment events can carry guest data inside authorized workflow execution history; customer webhooks contain notification metadata only.'),
  ]],
  ['outreach','Campaigns & sequences','Review consented audiences before email, SMS, AI voice or WhatsApp outreach.',[
    section('Connect before creating a draft','Open Outreach - Connections as owner/admin and connect a mailbox, SMS provider, QCall account or WhatsApp Business account. Set per-connection rolling daily/hourly limits. Defaults are 100/day and 20/hour; maxima 10,000/day and 2,000/hour. Limits apply across campaigns sharing the connection, including WhatsApp AI replies. Private credentials are encrypted per workspace and are not returned to the browser.'),
    section('Campaign or sequence','A Campaign sends one step once. A Sequence follows 1-20 steps on the same channel with 0-720 hours waiting before each step. Choose a CRM object and optionally a saved smart list. Source audience must contain at most 500 records; narrow the list before creating the draft. Financial objects cannot be audiences.','Email requires subject and message. SMS requires message or template variables. Voice requires an available QCall assistant and dialer. WhatsApp requires an approved template, matching language and text body parameters. Use {{record.data.name}} and other record context expressions for personalization; check actual field keys. Mixed-channel sequences are not available.'),
    section('Review and launch deliberately','Save the draft, open the audience review and inspect eligible count, sample recipients, skipped reasons and first step. Every contact needs Marketing consent=true plus a valid email or international phone with leading +country code. Duplicate addresses and channel suppressions are skipped. Add a consent checkbox to a custom contact object when needed.','An administrator confirms launch against the saved version and reviewed audience digest. If the draft or audience changed, review again. Verified/enabled connection and current provider choices/templates are required. Launch performs real sends/calls asynchronously; connecting, parsing cURL and reviewing do not. The launched steps/audience are immutable. Duplicate into a new draft to change them; newly matching smart-list contacts are not silently enrolled.'),
    section('Monitor and control follow-ups','Use campaign detail and Activity to inspect enrollments, execution errors and recent provider activity. Accepted means provider acceptance, not confirmed delivery. WhatsApp signed receipts can mark delivered/read. Email/SMS/voice do not have full delivery/open/click/bounce analytics. Unknown means acceptance was ambiguous; check the provider before making another attempt. Durable delivery reservations prevent automatic ambiguous resend.','Pause/resume controls future steps; cancel stops unfinished executions. Stop a contact to end that campaign’s follow-ups. Suppressions permanently blocks a normalized recipient for this workspace/channel and stops active sequences on that channel. There is no suppression-removal control in this release. Email unsubscribe and WhatsApp STOP also suppress. Matching email replies and WhatsApp incoming text stop remaining follow-ups; SMS and voice reply tracking are not implemented.'),
  ]],
  ['email','Email, Google & Outlook','Connect an SMTP/IMAP mailbox or authorize native Google and Microsoft access.',[
    section('SMTP with optional IMAP','In Connections, choose Email/SMTP. Enter sender email, public hostname, SMTP port 465 (TLS) or 587 (STARTTLS), username and password/app password. Certificate validation is required. If you want reply detection, add IMAP host/user/password; IMAP uses TLS port 993. Save verifies access without sending a test email. SMTP without IMAP can send but cannot detect mailbox replies.'),
    section('Native Google and Outlook','Choose Connect Google or Connect Outlook and finish provider consent using the account that started it. Mailbox authorization is separate from DryKraft login. Google needs Gmail send, Gmail read-only and email profile access. Outlook needs Mail.Send, Mail.Read, User.Read and offline_access. Offline refresh access is required. Cancellation returns to Connections; restart there if the ten-minute connection request expires.','Administrators deploying DryKraft must configure GOOGLE_OAUTH_CLIENT_ID/SECRET and MS_OAUTH_CLIENT_ID/SECRET privately. Register https://app.drykraft.com/api/outreach/oauth/google/callback and https://app.drykraft.com/api/outreach/oauth/microsoft/callback exactly with the respective provider apps. The existing callbacks were requested for registration; real consent and mailbox sends have not yet been verified in this deployment. Credentials being configured alone does not prove consent is ready.'),
    section('Replies and unsubscribe','Reply sync checks up to 50 recent headers about every five minutes, matches exact message ID plus sender, and only matches deliveries within 30 days. Google reads a seven-day inbox window. Use Sync replies when checking a connection. Matching replies stop future sequence work; unrelated mail does not.','Messages include unsubscribe links and one-click unsubscribe headers. The link confirmation names the company/channel and applies only to that workspace/channel. Open/click/bounce tracking and automatic invoice email delivery are not part of this release. Provider sending limits and mailbox consent requirements still apply.'),
  ]],
  ['sms','SMS provider setup','Paste a provider cURL, map its JSON parameters and reuse it for campaign steps.',[
    section('Use a literal provider example','Choose SMS connection and paste one HTTPS POST with a JSON object body. Enter private credentials only in the connection form. The parser reads request URL, headers and body; it never executes shell commands. Supported flags are request, URL, header and data/data-raw/data-binary. Files, shell substitutions/operators, redirects, proxies, localhost/private hosts and non-443 destinations are blocked.'),
    section('Map one recipient and the message','Inspect the body parameters, choose the existing recipient path, and optionally choose a message path. For an MSG91 flow with one recipients entry, recipient path is recipients.0.mobiles. Put {{variables.var}} in an existing template-variable body value and supply var in each SMS step; a generic text provider can use a message path instead.','Keep exactly one recipient entry in the source JSON when mapping array parameters. DryKraft enrolls and sends one recipient at a time. Stored recipient replacement uses the international phone without the leading +; make sure that format matches the provider. Config verification checks the destination and body, not provider authorization or message delivery.'),
    section('Review outcomes','A saved connection sends nothing. A confirmed campaign launch sends actual messages using the stored private headers/body and personalized variables. Activity reports request acceptance when the provider acknowledges it. SMS delivery receipts, incoming SMS replies and opt-out keywords are not wired; add manual channel suppression when appropriate.'),
  ]],
  ['voice','AI voice with QCall','Choose a workspace assistant and dialer for each reviewed outreach step.',[
    section('Connect the workspace account','Choose AI voice/QCall in Connections and enter your own QCall API key. Save reads assistants and dialers without placing a call. The development testing key is local-only and is not distributed in public docs or production connections. Each production workspace supplies its own provider access.'),
    section('Choose assistant and dialer','Select the assistant/dialer returned for this connection in every voice step. The reviewed contact must have consent and a valid international phone. At launch, DryKraft checks that the chosen options are still available. A voice campaign has one call step; a sequence can have multiple delayed steps.'),
    section('Understand provider acceptance','For each recipient/step, DryKraft creates a distinct provider tag/contact and automated QCall campaign. Acceptance is not evidence that a call connected or completed. Voice call outcome callbacks, transcript analytics and voice reply-based stopping are not available in this release. Check the provider before creating another attempt after an unknown result.'),
  ]],
  ['whatsapp','WhatsApp Business & AI replies','Use native Cloud API templates, signed webhooks and optional replies from your configured language model.',[
    section('Connect Meta Business','Choose WhatsApp and supply Meta access token, app secret, WhatsApp Business account ID (WABA) and phone number ID. The server verifies the phone belongs to that WABA. Provider Graph version defaults to v23.0 in this implementation. Save returns public connection details; private credentials remain encrypted. Use your provider account’s current permissions and approved templates.'),
    section('Register the webhook','Open the connection’s Webhook setup and copy its unique callback URL and verify token into your Meta app. Subscribe to the messages field and the WABA app subscription using the available control. A verified URL alone does not complete WABA subscription. The callback handles verification challenge, then validates X-Hub-Signature-256 against the raw body/app secret and checks WABA/phone IDs.','Signed receipts update accepted/delivered/read status, including receipts arriving before the send result. Incoming text is deduplicated and stops sequence follow-ups. STOP, unsubscribe, cancel and quit permanently suppress this workspace/channel. Other message types are not processed as inbound text.'),
    section('Launch approved template outreach','Choose an approved template and language, then supply matching text body parameters. Dynamic header and button parameters are not supported. Review the consented audience and launch as admin. Opening a connection or preview does not send a WhatsApp message. Meta authorization/template availability and actual sending were not verified through real customer messages during development.'),
    section('Enable AI replies deliberately','In the WhatsApp connection settings, write business instructions, try the unsent preview, then explicitly enable AI replies. A DryKraft administrator sets OUTREACH_LLM_URL, OUTREACH_LLM_MODEL and OUTREACH_LLM_API_KEY in the server environment. For 60db, use https://api.60db.ai/v1/chat/completions with model vyas and your own 60db API key. Incoming text and business instructions are sent to the configured provider. The generated plain-text reply is sent through this connection only for an eligible incoming message within the 24-hour conversation window, with billing access, connection limits and suppression checks.','The assistant has no tools for prices, appointments, account actions or transactions. Supply the facts it may use and review generated behavior. Preview calls the LLM but returns sent=false; it never sends to WhatsApp. Disabling the connection disables AI. Replacing credentials disables AI until deliberately re-enabled. There is no human handoff or external tool execution in this release.'),
  ]],
  ['team-security','Team access & account security','Invite the right people, protect administration and revoke unwanted sessions.',[
    section('Invite teammates','Open Settings - Team members as owner/admin. Enter email and select member or viewer; only the owner can grant admin. Create the seven-day invitation link, copy it and share it yourself. No invitation email is sent. A replacement revokes the previous link. The recipient uses the invited email’s existing account password or creates an account and joins directly.','Pending invitations do not consume paid seats. Accepting a new member needs an available paid seat when subscribed. Viewers can read records and use lists; members can edit business data; administrators manage workspace configuration and outreach launch. Owner controls billing and administrator access. Object/field/team policies and ownership transfer are not implemented.'),
    section('Change or remove access','Refresh the team before applying a role change/removal if another person edited access. Stale versions return a conflict. Owner access is protected. Removing a person invalidates their workspace sessions, revokes pending invitations sent by them and preserves business records/activity. Invitations and members paginate; expired invitations can be replaced or cancelled.'),
    section('Review your sessions','Open Settings - Security for your account across all workspaces. Inspect current and other active sessions, approximate browser/OS label, sign-in time, last activity and expiry. Older sessions may have unavailable metadata. Labels do not prove a physical device or location. Activity updates roughly every five minutes; sessions last seven days. End one session, all others or the current session after confirmation.'),
    section('Add two-step verification','Open Settings - Account security and choose Add an authenticator. Confirm your current password, scan the QR code or enter its key in an authenticator, then enter the current six-digit code within ten minutes. Cancel removes that pending setup and remains available after the proof-attempt limit. If a connection failure prevents server cancellation, the dialog still closes and explains that the pending setup expires ten minutes after it started; a new setup replaces it. Enabling ends previous sessions and keeps this browser signed in with a new session. The shared sample account cannot configure MFA.','Ten recovery codes appear once after confirmation. Save them privately and acknowledge that you saved them before leaving. Each works once for sign-in or a security approval. Password-first sign-in asks for an authenticator or recovery code before granting a session; the challenge expires in five minutes and allows five failed proofs. Codes already used cannot be replayed. If you used the current authenticator code, wait for the next one.','Replace recovery codes or turn off verification with current-password and authenticator or unused recovery-code approval. Replacing invalidates old codes; both changes revoke prior sessions and pending sign-ins. A lost response cannot retrieve the codes again: sign in with your authenticator and replace them. No email/SMS factor, WebAuthn, administrator bypass or mandatory workspace policy is included.'),
    section('Change your password','Enter current password, a different 10-128 character new password and confirmation. Saving rotates this session and ends every other account session. Password changes are limited to ten attempts per account per 15 minutes and disabled for the shared local sample. The private history shows the latest 20 account security events.','Forgot your password? Choose Forgot your password on the sign-in page and follow the email link. Reset links expire after 15 minutes, can be used once and end existing sessions. Email verification, login OAuth and magic links are not implemented. Service accounts and scoped API keys are managed separately in Developer access. Native Google/Outlook connection grants mailbox access for outreach; it is not account sign-in. For access problems contact support@drykraft.com without sharing passwords or session cookies.'),
  ]],
  ['billing','Billing, trial & Dodo checkout','Choose monthly or annual seat billing, or request a custom Enterprise quote.',[
    section('Trial and seat billing','Every new workspace receives a 15-day free trial without a payment card or automatic signup charge. Active workspace members use seats, including the owner, administrators, members and viewers. Pending invitations are excluded. CRM and finance currencies are configured separately from subscription billing. Review current subscription details in Settings - Billing.'),
    section('Start or manage the subscription','The workspace owner opens Settings - Billing, selects Monthly or Annual, chooses enough seats for current members and continues to Dodo’s hosted checkout. The provider checkout trial uses remaining free days rounded up, capped at 15 days. Dodo shows the trial end and first billing date before subscription. Confirm the final amount/taxes in checkout. Returning to DryKraft does not itself prove payment; signed webhooks/canonical provider refresh update status.','Use Refresh billing if provider status is pending. An ambiguous open checkout remains reserved for its 24-hour lifetime; contact support rather than opening another purchase blindly. Once subscribed, the Dodo portal manages payment methods, subscription invoices and cancellation. Seat changes apply immediately without an immediate charge; the next scheduled renewal uses the new price. Remove members before reducing below the member count.'),
    section('Annual checkout API and payment grace','The checkout API accepts the configured annual or monthly billing interval. It validates the configured continuing product before creating checkout, then binds the chosen product and interval to the saved request. An open checkout cannot be reused for a different interval. The customer interval selector is deployed and the live unpaid hosted checkout has passed acceptance. Successful payment and paid renewal acceptance remain pending. Saved subscriptions and open checkout lock their interval; an open checkout also locks its saved seats.','A canonical provider past_due status can retain access only until its supplied past_due_ends_at deadline, with purchased-seat and workspace/module restrictions still applied. Missing or elapsed grace does not grant access. On_hold does not reuse a grace date; use the hosted Dodo portal for payment-method recovery.'),
    section('Expired access and Enterprise','After trial/paid access ends, records remain readable and account security/billing remain usable. Most business changes and automation require an active plan; access removal is still available. Cancellation handling comes from the provider’s current subscription state and next billing date.','Enterprise terms and scope are agreed directly. An active agreement shows its agreed seats and access end date; an agreement without a provider subscription hides the self-service purchase form. Existing provider subscriptions are managed separately. Save organization requirements in Billing and contact support@drykraft.com. A request does not activate a contract, paid access or additional features. Dodo bills the DryKraft subscription; it does not collect your customer invoice payments.'),
    section('Billing webhook setup','The deployment uses https://app.drykraft.com/api/billing/dodo/webhook. Configure the endpoint and matching private signing secret with the Dodo account. Raw request bytes plus webhook-id/timestamp/signature are verified with a five-minute timestamp window. Duplicate events are ignored and current provider subscription state is fetched. Keep API/signing secrets in private server configuration, never in frontend code or documentation.'),
  ]],
  ['troubleshooting','Troubleshooting & release limits','Recover from stale changes, provider failures and setup issues without duplicating side effects.',[
    section('Sign-in and workspace access','401: sign in again; expired or revoked sessions cannot be reused. 403: check workspace membership/role and selected hostname. 409 during setup: complete onboarding. If a team link returns 410, ask the administrator for a fresh invitation. Workspace subdomains are enabled. If a chosen address is not reachable, use app.drykraft.com and contact support to check the address. For an expired session, choose Forgot your password on the sign-in page. Reset links expire after 15 minutes and can be used once.'),
    section('Conflicts and invalid input','409 on a record/list/dashboard/member means data changed or is unavailable. Refresh, review current values and reapply the intended edit. Do not silently remove version checks. 400 means an invalid field, relation, state transition, CSV row or provider configuration; correct the message before saving. A valid preview can become stale before commit/launch.'),
    section('Billing and provider failures','402 means an active plan is needed; the owner manages Billing. 429 means a rate limit: wait for the indicated window and reduce requests. Provider errors may be 502/503. Check authorization, connection choices and current provider status. An Unknown outreach outcome may already have been accepted: inspect the provider before creating a new campaign/attempt. Cancelling cannot recall a message or call already accepted.'),
    section('What this release does not include','The current release covers the documented modules and APIs; the full PRD is still in progress. Not implemented: customer custom domains, full marketing/social modules, mixed-channel outreach, audiences above 500 per launch, automatic invoice email/customer collection/bank reconciliation, arbitrary SQL/formula dashboards, login OAuth, granular permission policies, ownership transfer and suppression removal.','Scalability depends on workload and deployment capacity. JSON field filters currently scan the selected object; large-data indexes, queue throughput tuning, monitoring/recovery drills and a key-rotation migration remain operational work. The product is responsive and configurable within documented limits; no unlimited scalability or 100% customization guarantee is implied.'),
    section('Get help with useful context','Contact support@drykraft.com with the page, action, time and X-Request-ID if available. Include the recovery message and a redacted screenshot. Do not share account passwords, provider secrets, invitation/hook tokens, session cookies or customer data unnecessarily.'),
  ]],
];

export const docsPages=[
  {path:'/docs',title:'DryKraft documentation',description:'Product guides and complete current API reference for DryKraft CRM, sales, finance, automation and outreach.'},
  ...productChapters.map(([slug,title,description])=>({path:'/docs/product/'+slug,title,seoTitle:title+' - Product guide',description})),
  {path:'/docs/api',title:'API reference',description:'Learn DryKraft session authentication, workspace context, permissions, limits, errors and examples before using its current API.'},
  ...apiGroups.map(([slug,title])=>({path:'/docs/api/'+slug,title,seoTitle:title+' - API reference',description:`DryKraft ${title} reference: methods, permissions, request fields, response shapes, examples and current limits.`})),
  {path:'/docs/api/schemas',title:'API data schemas',description:'Field definitions, records, finance drafts, filters, widgets, workflow graphs and outreach schemas for the DryKraft API.'},
];
const docsLink=(path,title)=>`<a href="${path}">${esc(title)}</a>`;
function nav(page){return `<details class="docs-chapters" open><summary>Browse documentation</summary><div class="docs-chapter-body"><label for="docs-search">Find a chapter</label><input id="docs-search" type="search" placeholder="Try invoices or WhatsApp" aria-describedby="docs-search-help"><p id="docs-search-help">Search chapter titles and summaries.</p><p id="docs-search-result" role="status" hidden></p><button type="button" id="docs-search-clear" hidden>Clear search</button><nav aria-label="Documentation chapters"><a href="/docs"${page.path==='/docs'?' aria-current="page"':''}>Documentation home</a><h2>Product guides</h2>${productChapters.map(([slug,title,description])=>`<a data-doc-chapter data-search="${esc(title+' '+description)}" href="/docs/product/${slug}"${page.path==='/docs/product/'+slug?' aria-current="page"':''}>${esc(title)}</a>`).join('')}<h2>API reference</h2>${[['','API overview'],...apiGroups,['schemas','Data schemas']].map(([slug,title])=>`<a data-doc-chapter data-search="${esc(title)}" href="/docs/api${slug?'/'+slug:''}"${page.path==='/docs/api'+(slug?'/'+slug:'')?' aria-current="page"':''}>${esc(title)}</a>`).join('')}</nav></div></details>`;}
const headingId=title=>title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/-$/,'');
function toc(sections){return `<nav class="docs-toc" aria-label="On this page"><span>On this page</span>${sections.map(s=>docsLink('#'+(s.id||headingId(s.title)),s.title)).join('')}</nav>`;}
function prose(sections){return sections.map(s=>`<section id="${headingId(s.title)}" class="docs-section"><h2>${esc(s.title)}</h2>${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</section>`).join('');}
function code(value,label='Example'){return `<div class="docs-code"><div><span>${esc(label)}</span><button type="button" data-copy-code aria-label="Copy ${esc(label)}">Copy</button></div><pre tabindex="0"><code>${esc(value)}</code></pre></div>`;}
const sampleId='00000000-0000-4000-8000-000000000001';
function sample(schema,depth=0){
  if(depth>7)return {};
  if(schema.$ref)return sample(apiSchemas[schema.$ref.split('/').at(-1)],depth+1);
  if(schema.const!==undefined)return schema.const;
  if(schema.enum)return schema.enum[0];
  if(schema.oneOf)return sample(schema.oneOf[0],depth+1);
  if(schema.format==='uuid')return sampleId;
  if(schema.format==='email')return 'person@example.com';
  if(schema.format==='date')return '2026-10-02';
  if(schema.type==='object')return Object.fromEntries((schema.required||[]).map(k=>[k,sample(schema.properties[k],depth+1)]));
  if(schema.type==='array')return Array.from({length:schema.minItems||0},()=>sample(schema.items,depth+1));
  if(schema.type==='integer'||schema.type==='number')return schema.minimum??1;
  if(schema.type==='boolean')return false;
  if(schema.pattern===keyPattern)return 'people';
  return schema.default??'<'+(schema.description?.split(/[.,]/)[0]||'value')+'>';
}
const keyPattern='^[a-z][a-z0-9_]{1,39}$';
const invoiceExample={name:'Example consulting invoice',customer_name:'Example Company',currency:'USD',issue_date:'2026-10-02',due_date:'2026-11-01',items:[{description:'Consulting',quantity:'1',unit_price:'100.00',discount:'0',tax_rate:'0'}]};
const campaignExample={name:'Example email follow-up',kind:'campaign',channel:'email',object_key:'people',list_id:null,connection_id:sampleId,steps:[{waitHours:0,subject:'Hello {{record.data.name}}',body:'Following up on your request.'}]};
function requestExample(op){
  if(op.group==='templates'&&op.body)return op.path.endsWith('invoice-preview')?{title:'Invoice',footer:'Thank you for your business.',accent:'#bf3d05'}:{name:'Customer follow-up',kind:'email',content:{subject:'Hello {{record.data.name}}',body:'Thank you for your interest.'},archived:false,...(op.method==='POST'?{id:sampleId}:{version:1})};
  if(op.group==='developer-access'&&op.body){const input=sample(op.body);if(input.permissions)input.permissions={people:['read']};if(input.password)input.password='<CURRENT_PASSWORD>';return input;}
  if(op.group==='versioned-crm'&&op.body)return op.path.endsWith('/activities')?{body:'Example internal note'}:op.method==='DELETE'?{version:1}:{data:{name:'Example person'},...(op.method==='PATCH'?{version:1}:{})};
  if(op.path.startsWith('/api/records/'))return {data:{name:'Example person'},...(op.method==='PUT'?{version:1}:{})};
  if(op.path==='/api/finance/{key}'||op.path==='/api/finance/{key}/{id}')return {data:invoiceExample,...(op.method==='PUT'?{version:1}:{})};
  if(op.path==='/api/outreach/campaigns'||op.path==='/api/outreach/campaigns/{id}')return {...campaignExample,...(op.method==='PUT'?{version:1}:{})};
  if(op.path==='/api/outreach/connections')return {name:'Example SMTP mailbox',provider:'smtp',daily_limit:100,hourly_limit:20,secret:{email:'sender@example.com',host:'smtp.example.com',port:587,user:'sender@example.com',password:'<APP_PASSWORD>'}};
  if(op.path==='/api/objects')return {key:'projects',name:'Projects',singular_name:'Project',fields:[{key:'name',name:'Project name',type:'text',required:true}]};
  if(op.path==='/api/objects/{key}/fields')return {key:'region',name:'Region',type:'text',required:false};
  if(op.path==='/api/auth/onboarding')return {workspace:'Example Company',slug:'example-company',currency:'USD',currencies:['USD','INR','EUR','KWD']};
  if(op.path.includes('/import/'))return {csv:'name,email\nExample Person,person@example.com\n',duplicates:'skip',...(op.path.endsWith('/commit')?{id:sampleId}:{})};
  return sample(op.body);
}
const schemaType=s=>s.$ref?s.$ref.split('/').at(-1):s.allOf?s.allOf.map(schemaType).join(' and '):s.oneOf?s.oneOf.map(schemaType).join(' or '):s.enum?s.enum.map(String).join(' | '):s.const!==undefined?String(s.const):s.type==='array'?schemaType(s.items)+'[]':(Array.isArray(s.type)?s.type.join(' or '):s.format||s.type||'value');
function schemaLink(s){return s.$ref?docsLink('/docs/api/schemas#schema-'+s.$ref.split('/').at(-1),s.$ref.split('/').at(-1)):s.allOf?s.allOf.map(schemaLink).join(' and '):s.oneOf?s.oneOf.map(schemaLink).join(' or '):s.type==='array'?schemaLink(s.items)+'[]':esc(schemaType(s));}
function schemaTable(schema,kind='Field'){
  if(schema.$ref)return `<p>Use ${schemaLink(schema)}. ${esc(apiSchemas[schema.$ref.split('/').at(-1)].description||'')}</p>`;
  const bases=(schema.allOf||[]).map(s=>schemaTable(s,kind)).join('');
  if(!schema.properties)return bases|| `<p>${schemaLink(schema)}. ${esc(schema.description||schema.items?.description||'')}</p>`;
  return `${bases}${schema.description?`<p>${esc(schema.description)}</p>`:''}<div class="docs-table" tabindex="0" aria-label="${esc(kind)} definitions"><table><thead><tr><th>${esc(kind)}</th><th>Type</th><th>Required</th><th>Details</th></tr></thead><tbody>${Object.entries(schema.properties).map(([name,s])=>`<tr><th scope="row"><code>${esc(name)}</code></th><td>${schemaLink(s)}</td><td>${schema.required?.includes(name)?'Yes':'No'}</td><td>${esc(s.description||'')}${s.minimum!==undefined?` Min ${s.minimum}.`:''}${s.maximum!==undefined?` Max ${s.maximum}.`:''}${s.maxLength?` Max ${s.maxLength} characters.`:''}${s.minItems?` Min ${s.minItems} items.`:''}${s.maxItems?` Max ${s.maxItems} items.`:''}${s.pattern?` Pattern: <code>${esc(s.pattern)}</code>.`:''}</td></tr>`).join('')}</tbody></table></div>`;
}
function operation(op){
  const requiredQuery=Object.entries(op.query).filter(([name])=>op.queryRequired.includes(name));
  const endpoint=op.path.replaceAll('{id}',sampleId).replaceAll('{requestId}',sampleId).replaceAll('{memberId}',sampleId).replaceAll('{planId}',sampleId).replaceAll('{keyId}',sampleId).replaceAll('{deliveryId}',sampleId).replaceAll('{resource}','contacts').replaceAll('{record}',sampleId).replaceAll('{key}',op.group==='finance'?'invoices':'people').replaceAll('{name}','won-deal').replaceAll('{provider}','google').replaceAll('{token}','<PRIVATE_TOKEN>')+(requiredQuery.length?'?'+requiredQuery.map(([name,s])=>name+'='+encodeURIComponent(name==='slug'?'example-company':sample(s))).join('&'):'');
  const publicRequest=op.access==='Public';
  const platformRequest=op.path.startsWith('/api/sa/');
  const resellerRequest=op.path.startsWith('/api/reseller/');
  const bearer=['Scoped API key','Scoped reseller API key'].includes(op.access),mutation=op.access==='Scoped API key'&&['POST','PATCH','DELETE'].includes(op.method);
  const bearerPlaceholder=op.access==='Scoped reseller API key'?'<YOUR_RESELLER_API_KEY>':'<YOUR_API_KEY>';
  const command=[`curl --request ${op.method}`,`--url 'https://app.drykraft.com${endpoint}'`,
    ...(publicRequest?[]:bearer?[`--header 'Authorization: Bearer ${bearerPlaceholder}'`]:[`--cookie '${platformRequest?'drykraft_sa_session':resellerRequest?'drykraft_reseller_session':'drykraft_session'}=<YOUR_SESSION_TOKEN>'`]),
    ...((platformRequest||resellerRequest)&&['POST','PUT','PATCH','DELETE'].includes(op.method)?["--header 'Origin: https://app.drykraft.com'"]:[]),
    ...(mutation?["--header 'Idempotency-Key: <REQUEST_UUID>'"]:[]),
    ...(op.body?["--header 'Content-Type: application/json'","--data '"+JSON.stringify(requestExample(op),null,2)+"'"]:[])
  ].join(' \\\n  ');
  return `<section id="${op.id}" class="docs-operation"><div class="docs-endpoint"><span>${op.method}</span><code>${esc(op.path)}</code></div><h2>${esc(op.title)}</h2><p class="docs-access">Access: ${esc(op.access)} · Success: ${op.status}</p><p>${esc(op.description)}</p>${Object.keys(op.query).length?`<h3>Query parameters</h3>${schemaTable({properties:op.query,required:requiredQuery.map(([name])=>name)},'Parameter')}`:''}${op.body?`<h3>JSON request</h3>${schemaTable(op.body)}`:'<p>No request body is required.</p>'}<h3>Response</h3>${schemaTable(op.response)}${['Dodo signature','Meta signature','Meta verify token','Secret hook token','Secret unsubscribe token'].includes(op.access)||op.status===302?'<p>Use the provider configuration or private generated link described above; this is not a session-based example.</p>':code(command,'Request shape (illustrative)')}</section>`;
}
function apiOverview(){return `${prose([
  section('Base URL and scope','Use https://app.drykraft.com/api for browser/session routes, and /api/v1 for service-account CRM access with scoped Bearer keys. The complete current reference includes public provider callbacks. It is not a promise that the full PRD is implemented. Signed customer webhooks are managed in Settings - Webhooks. The external SDK remains outstanding. OpenAPI includes customer session, service-account key and separate platform session schemes.'),
  section('Service-account access','Owners/admins configure explicit object/action permissions and expiring keys in Settings - Developer access. Use Authorization: Bearer; a cookie cannot substitute under /api/v1. The key is fixed to its workspace, and X-Workspace-ID or another workspace hostname cannot switch it. Browser/account/billing/provider/administrator routes do not accept this key. GET /api/v1/me shows effective permissions and expiry. Each authorized object includes all its fields and owners.','Versioned CRM reads use the shared cursor/filter contract; PATCH requires the current version and preserves omitted fields. Every POST/PATCH/DELETE requires a stable UUID Idempotency-Key. Identical retries on that service account/path/payload return the original result with Idempotency-Replayed=true. A different request conflicts. Preserve field order when retrying; the validated serialized JSON must match. Current permission and active billing are checked before replay. Financial access is Read/Add notes only. Business events/audit identify the service account separately from users.'),
  section('Authenticate and select a workspace','POST /api/auth/login with email/password or use signup. For an MFA-enabled account, login returns a five-minute challenge and creates no session; POST /api/auth/mfa with that challenge and a new authenticator or unused recovery code. After success retain the HTTP-only drykraft_session cookie. Production uses Secure, SameSite=Lax and a seven-day lifetime. Browser clients should make same-origin requests with credentials included. State-changing Origin headers must match the request host; cross-origin browser integration is not enabled.','Read /api/session to get accessible workspace IDs and current role. Use /api/session/workspace to select a member workspace. X-Workspace-ID can select another workspace you belong to per request, but cannot bypass membership or workspace hostname checks. A tenant_id in a request body does not grant access. Account-security endpoints require an account session even before onboarding; most other protected endpoints require a selected workspace.'),
  section('Roles, billing and state','Workspace member means owner/admin/member/viewer can read. Owner, admin or member can change business data; viewer is read-only. Configuration/launch generally needs owner/admin. Only owner manages billing and administrators. Endpoint descriptions name finer constraints. Most writes need active trial/paid access; account security, billing and access removal remain available after expiry.','For versioned records, smart lists, dashboards and member changes, read the latest version and submit it. A 409 must trigger a refresh and review. Record PUT replaces complete data; bulk update merges specified fields. Financial records must use Finance, not generic record writes. Launched outreach/immutable workflow versions cannot be rewritten.'),
  section('Pagination and request limits','Use next_cursor as an opaque token and keep search/filter settings unchanged while paging. Records default to 50 rows, max 100; team/session pages use 25. Some history endpoints intentionally return only a recent bounded list and have no next page. Returned metadata can include additional row fields; do not depend on fields outside documented contracts.','JSON request bodies are capped at 512 KB. General /api has 300 requests/minute per client IP; authentication and generic workflow hooks share 30 attempts/15 minutes. Raw Dodo and Meta notifications each have a separate 120 requests/minute per IP. Calendar adds 120 requests/minute; public booking and guest changes share 15 attempts/15 minutes. These counters use shared Redis across API servers and survive an API restart. IPv6 addresses share their /56 subnet allowance.','Account password changes additionally allow ten attempts per account/15 minutes; authenticator setup/management and MFA proofs share another ten attempts per account/15 minutes; service-account requests have 120/minute per key, and access approval has 30 attempts per administrator/15 minutes. Fixed windows begin with the first attempt; unsuccessful requests count too. IP limits return RateLimit and RateLimit-Policy headers; blocked requests include Retry-After. Wait for the indicated window. Sending quotas for providers/connections are separate. A 413 can have a non-JSON parser response.'),
  section('Errors and safe retry','Normal errors and blocked requests are {error:{message,request_id}} with X-Request-ID; parser/provider ingress responses can differ. 400 input validation, 401 sign-in/signature, 402 subscription, 403 permission, 404 resource, 409 conflict, 410 invitation expiry, 413 body size, 429 rate limit and 5xx server/provider failure. Preserve the request ID when requesting support.','If shared request protection is unavailable or stalls, affected API requests return 503 with Retry-After: 5 instead of proceeding without protection. The business handler does not run. A timed-out counter may still consume an attempt. Do not rapidly retry. Public HTML remains available; Redis service failure or loss is separate from an API restart.','Use a stable UUID for CSV commit/payment entry retries with identical content. Generic workflow hooks accept Idempotency-Key. Versioned CRM mutations require a UUID Idempotency-Key. Other browser creates/launches do not have a universal idempotency key. A network failure is not proof of failure: refresh state before retrying payment checkout, outreach launch or external execution. Unknown outreach results require provider inspection; do not blindly resend.'),
])}${code("curl --request POST \\\n  --url 'https://app.drykraft.com/api/auth/login' \\\n  --cookie-jar ./drykraft-session.txt \\\n  --header 'Content-Type: application/json' \\\n  --data '{\"email\":\"you@example.com\",\"password\":\"<YOUR_PASSWORD>\"}'\n\ncurl --url 'https://app.drykraft.com/api/session' \\\n  --cookie ./drykraft-session.txt",'Sign in and read session')}<p>The example uses your private account only. Keep the local cookie file private and delete it when done. Never paste credentials into shared docs, logs or screenshots. Replace angle-bracket placeholders before running examples.</p><h2 id="api-groups">Find an API group</h2><div class="docs-index">${apiGroups.map(([slug,title])=>docsLink('/docs/api/'+slug,title+' ('+apiOperations.filter(o=>o.group===slug).length+' operations)')).join('')}</div><p>${docsLink('/docs/api/schemas','Browse data schemas')} · ${docsLink('/docs/openapi.json','Download OpenAPI 3.1 JSON')}</p>`;}
export function renderDocumentation(page){
  let body,sections=[];
  if(page.path==='/docs')body=`<p class="docs-intro">Set up your workspace, follow the product workflows or look up an API request. These guides describe the current release and its limits.</p><div class="docs-start"><a href="/docs/product/getting-started"><strong>Product guides</strong><span>Start a workspace, then configure the work your team does.</span></a><a href="/docs/api"><strong>API reference</strong><span>${apiOperations.length} operations, session or scoped key authentication, examples and schemas.</span></a></div><h2 id="product-guides">Explore the product</h2><div class="docs-index">${productChapters.map(([slug,title,description])=>`<a href="/docs/product/${slug}"><strong>${esc(title)}</strong><span>${esc(description)}</span></a>`).join('')}</div><h2 id="developer-resources">For developers</h2><p>Read authentication and workspace rules before integrating. Every current endpoint is listed by module, including raw provider callbacks. Examples are illustrative and contain placeholders; documentation controls never send requests.</p><div class="docs-index">${docsLink('/docs/api','Authentication, errors and safe retries')}${docsLink('/docs/api/schemas','Shared data schemas')}${docsLink('/docs/openapi.json','Download OpenAPI 3.1 JSON')}</div><p>Need help? <a href="mailto:support@drykraft.com">support@drykraft.com</a></p>`;
  else if(page.path.startsWith('/docs/product/')){const chapter=productChapters.find(c=>page.path.endsWith('/'+c[0]));sections=chapter[3];body=`<p class="docs-intro">${esc(chapter[2])}</p>${toc(sections)}${prose(sections)}`;}
  else if(page.path==='/docs/api')body=apiOverview();
  else if(page.path==='/docs/api/schemas'){sections=Object.keys(apiSchemas).map(name=>({id:'schema-'+name,title:name}));body=`<p class="docs-intro">Shared request and response shapes. Field descriptions include bounds and state-dependent requirements. See each endpoint for permissions and additional validation.</p>${toc(sections)}${Object.entries(apiSchemas).map(([name,s])=>`<section id="schema-${name}" class="docs-section"><h2>${name}</h2>${schemaTable(s)}${code(JSON.stringify(s,null,2),name+' JSON Schema')}</section>`).join('')}`;}
  else {const group=page.path.split('/').at(-1),ops=apiOperations.filter(o=>o.group===group);body=`<p class="docs-intro">${esc(page.description)} ${docsLink('/docs/api','Read authentication and error handling first')}.</p>${toc(ops)}${ops.map(operation).join('')}`;}
  return `<div class="docs-layout">${nav(page)}<article class="docs-article"><header class="docs-heading"><h1>${esc(page.title)}</h1><p class="docs-updated">Current release · Updated October 4, 2026</p></header>${body}<footer class="docs-article-footer"><a href="/docs">Documentation home</a><a href="/docs/api">API overview</a><a href="mailto:support@drykraft.com">Get support</a></footer></article></div><p class="docs-copy-status" role="status" aria-live="polite"></p>`;
}
